// =====================================================================
// W28 d1：回顾 —— 时间系统原来在哪。
//
// 在 S8 开工之前，时间三对象（CalendarEvent / Todo / Reminder）是
// HomeOS 的三张表：homeos_calendar_event / homeos_todo / homeos_reminder。
// 它们和身份、权限、通知挤在同一个 schema、同一条迁移序列里。
//
// 本程序用内存结构模拟「抽离前」的 homeos schema，把三张表摆出来，
// 然后逐个回答三个问题：
//   ① 它们被谁写？谁读？（横切依赖清单）
//   ② 它们的前缀、表名、路由、事件前缀是什么？（全带 homeos）
//   ③ 它们的生命周期跟着谁走？（HomeOS 的生命周期）
//
// 结论埋在最后一节：横切能力没有自己的 code，就无法被门禁如实描述。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"unicode"
)

// ---- 中文对齐：终端里一个汉字占 2 列，所以要按显示宽度算，不按 rune 数 ----
func dispWidth(s string) int {
	w := 0
	for _, r := range s {
		switch {
		case unicode.Is(unicode.Han, r):
			w += 2 // 汉字
		case r >= 0x1100 && r <= 0x115F, // 谚文字母
			r >= 0x2E80 && r <= 0xA4CF && r != 0x303F, // CJK 部首 ~ 彝文
			r >= 0xAC00 && r <= 0xD7A3,                // 谚文音节
			r >= 0xF900 && r <= 0xFAFF,                // CJK 兼容表意
			r >= 0xFE30 && r <= 0xFE6F,                // CJK 兼容形式
			r >= 0xFF00 && r <= 0xFF60,                // 全角 ASCII
			r >= 0xFFE0 && r <= 0xFFE6:
			w += 2 // 全角形式
		default:
			w++
		}
	}
	return w
}

func pad(s string, width int) string {
	n := width - dispWidth(s)
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// ---- 抽离前的三张表（表前缀全是 homeos_）----
type OldTable struct {
	Name    string   // 表名
	Owner   string   // 谁的服务拥有它（今天是 homeos）
	Col     []string // 关键列
	Written []string // 谁写它
	Read    []string // 谁读它
}

// 抽离前：三张表都归 homeos，前缀都是 homeos_
var oldTables = []OldTable{
	{
		Name:  "homeos_calendar_event",
		Owner: "homeos",
		Col:   []string{"id", "family_id", "source_system", "source_id", "title", "start_at", "end_at", "members", "repeat", "visibility"},
		// 写它的人：homeos 自己的聚合任务 + 各业务面（finance 的账单、周期记账）
		Written: []string{"homeos（到期聚合任务）", "finance（注册账单到期）", "finance（注册周期记账到期）"},
		// 读它的人：homeos 首页聚合 + 客户端日历页 + finance 自己（深链回源）
		Read: []string{"homeos（home/summary 的 due_today）", "客户端（日历页三视图）", "finance（深链回源对象）"},
	},
	{
		Name:    "homeos_todo",
		Owner:   "homeos",
		Col:     []string{"id", "family_id", "member_id", "title", "due_at", "status", "source_system", "source_id", "done_returns_to"},
		Written: []string{"homeos", "客户端（创建/完成待办）"},
		Read:    []string{"客户端（待办列表）", "homeos（due_today）", "finance（完成回写后刷新）"},
	},
	{
		Name:    "homeos_reminder",
		Owner:   "homeos",
		Col:     []string{"id", "owner_id", "type", "trigger_at", "repeat", "status", "calendar_event_id"},
		Written: []string{"homeos（到点触发任务）"},
		Read:    []string{"客户端（提醒列表）", "homeos（触发后落 Notification）"},
	},
}

// ---- 抽离前，一个进程里要同时干的活 ----
type Job struct {
	Name    string
	Belongs string // 它的「性质」：连接类 / 到期触发类
	Detail  string
}

// HomeOS 的职责清单（抽离前）
var homeosJobs = []Job{
	{"登录 / 签发 token", "连接", "身份、家庭、成员、权限"},
	{"家庭面配置", "连接", "哪些面开通了"},
	{"站内通知下发 + 未读口径", "连接", "Notification 与 99+ 上限"},
	{"动态流 / 留言板", "连接", "协作类内容"},
	{"home/summary 首页聚合", "连接", "跨面读，但要读到期数据"},
	{"到期扫描：每分钟扫 trigger_at", "到期触发", "找出到点的 Reminder，发通知"},
	{"周期规则展开：算下一个触发日", "到期触发", "repeat 字段的解释权在这里"},
	{"注册去重键", "到期触发", "(source_system, source_id, kind)"},
}

// ---- 「没有自己的 code」的具体表现 ----
// 门禁要回答的问题是：「这张表属于哪个服务？」
// 抽离前，三张时间表的答案是 homeos，但它们干的事和 homeos 的定位不符。

type GateCheck struct {
	Item   string
	Before string // 抽离前的答案
	After  string // 抽离后的答案
}

var gateChecks = []GateCheck{
	{"表归属", "3 张混在 14 张里，要靠人记", "时间表全在 calendar_ 前缀"},
	{"schema", "homeos（和身份权限同一个）", "calendar（独立账号、独立权限）"},
	{"迁移序列", "homeos 序列，和权限表改动互相卡", "calendar 序列，与 homeos 无关"},
	{"事件前缀", "homeos.* —— 和权限事件混在一个命名空间", "calendar.* —— 独立前缀"},
	{"路由域", "/api/homeos/*（和登录接口同域）", "/api/calendar/*（独立域）"},
	{"故障域", "到期扫描 OOM 了，登录一起挂", "只影响到期，登录与权限照常"},
}

func main() {
	fmt.Println("=== W28 d1 · 回顾：时间系统原来在哪 ===")
	fmt.Println()

	// ---------- 1. 三张表 ----------
	fmt.Println("=== 1. 抽离前：HomeOS 里的三张时间表 ===")
	fmt.Println()
	for _, t := range oldTables {
		fmt.Printf("  %s   （owner = %s）\n", t.Name, t.Owner)
		fmt.Printf("    关键列  %s\n", strings.Join(t.Col, ", "))
		fmt.Printf("    谁写    %s\n", strings.Join(t.Written, "；"))
		fmt.Printf("    谁读    %s\n", strings.Join(t.Read, "；"))
		fmt.Println()
	}

	// ---------- 2. 谁在横切依赖它 ----------
	fmt.Println("=== 2. 横切依赖：写它的人比拥有它的服务多 ===")
	fmt.Println()
	for _, t := range oldTables {
		fmt.Printf("  %-24s 写入方 %d 个 / 读取方 %d 个\n", t.Name, len(t.Written), len(t.Read))
	}
	fmt.Println()
	fmt.Println("  结论：三张表的写入方里出现了 finance —— 另一个业务面。")
	fmt.Println("        这就是「横切」的字面含义：它被全部业务面依赖。")
	fmt.Println()

	// ---------- 3. HomeOS 的职责清单：两种性质混在一起 ----------
	fmt.Println("=== 3. 抽离前 HomeOS 的职责清单（注意两种性质混排）===")
	fmt.Println()
	fmt.Printf("  %s %s %s %s\n", pad("#", 4), pad("职责", 30), pad("性质", 12), "说明")
	fmt.Println("  " + strings.Repeat("-", 92))
	for i, j := range homeosJobs {
		fmt.Printf("  %s %s %s %s\n", pad(fmt.Sprint(i+1), 4), pad(j.Name, 30), pad(j.Belongs, 12), j.Detail)
	}
	fmt.Println()

	conn, due := 0, 0
	for _, j := range homeosJobs {
		if j.Belongs == "连接" {
			conn++
		} else {
			due++
		}
	}
	fmt.Printf("  合计 %d 项职责：连接类 %d 项、到期触发类 %d 项，混在同一个进程里。\n", len(homeosJobs), conn, due)
	fmt.Println()

	// ---------- 4. 门禁视角：六个问题抽离前后 ----------
	fmt.Println("=== 4. 门禁视角：同一个问题，抽离前后的答案 ===")
	fmt.Println()
	fmt.Printf("  %s %s %s\n", pad("检查项", 12), pad("抽离前", 46), "抽离后")
	fmt.Println("  " + strings.Repeat("-", 96))
	for _, g := range gateChecks {
		fmt.Printf("  %s %s %s\n", pad(g.Item, 12), pad(g.Before, 46), g.After)
	}
	fmt.Println()

	// ---------- 5. 抽离前最容易卡住的三个时刻 ----------
	fmt.Println("=== 5. 抽离前，三个「说不清」的时刻 ===")
	fmt.Println()
	blurry := []struct {
		Scene string
		Why   string
	}{
		{"改一个日历字段，要不要动 homeos 的迁移序列？",
			"要。动 homeos 序列就意味着和权限、通知的变更同批上线，出事时说不清是时间的问题还是权限的问题。"},
		{"到期扫描任务崩了，登录还能不能用？",
			"不能用。两者在同一个进程，没有独立的健康检查与重启策略。"},
		{"有人问「这张 homeos_todo 表算 homeos 的吗」，",
			"代码上是的，业务上不是。它属于时间系统，而时间系统被定义为系统级面。归属与现实不符，门禁就无从校验。"},
	}
	for i, b := range blurry {
		fmt.Printf("  场景 %d：%s\n", i+1, b.Scene)
		fmt.Printf("          说不清的原因：%s\n", b.Why)
	}
	fmt.Println()

	// ---------- 6. 今天这一天的结论 ----------
	fmt.Println("=== 6. 今日结论 ===")
	fmt.Println()
	fmt.Println("  时间系统原来在 HomeOS 里，占 3 张表、8 项职责里的 3 项。")
	fmt.Println("  它被 finance 和客户端横切依赖，但它自己没有 code。")
	fmt.Println()
	fmt.Println("  明天回答：既然它被所有人依赖，为什么抽离出来反而更清晰？")
	fmt.Println()

	// ---------- 附：写入方去重排序（确定性输出）----------
	fmt.Println("=== 附：写入方去重排序 ===")
	seen := map[string]bool{}
	var writers []string
	for _, t := range oldTables {
		for _, w := range t.Written {
			head := strings.Split(w, "（")[0]
			if !seen[head] {
				seen[head] = true
				writers = append(writers, head)
			}
		}
	}
	sort.Strings(writers)
	for i, w := range writers {
		fmt.Printf("  %d. %s\n", i+1, w)
	}
	fmt.Printf("  共 %d 个写入方，其中只有 1 个（homeos）是它名义上的主人。\n", len(writers))
}

// =====================================================================
// W28 d2：它为什么被抽离出来 —— 横切能力没有自己的 code。
//
// d1 讲的是「它原来在哪」，今天讲「为什么必须走」。
//
// 关键论点只有一句：**横切能力没有自己的 code，就无法被门禁如实描述。**
//
// 本程序用一个可运行的模型证明这句话：
//   ① 建一个「门禁」—— 它的规则是「每张表必须能说出自己的服务归属」
//   ② 把它跑在「抽离前」的表清单上 → 门禁报红，且指出「说不清」
//   ③ 加一个 code = calendar，把表清单改成抽离后 → 门禁变绿
//
// 顺带把 tech-plan §1.3 的四维对照表跑成可执行的「四个维度打分器」，
// 让「四个维度的好处」不是背表格而是算出来的。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func pad(s string, w int) string {
	// 简易版：汉字占 2 列
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// ---- 一张表的自述：它属于哪个服务？----
type TableCard struct {
	Table    string
	Declared string // 代码上声明的归属（表前缀反推）
	Business string // 业务上真正的归属
	Verdict  string
}

var beforeTables = []TableCard{
	{"homeos_family", "homeos", "homeos", "一致"},
	{"homeos_member", "homeos", "homeos", "一致"},
	{"homeos_role", "homeos", "homeos", "一致"},
	{"homeos_permission", "homeos", "homeos", "一致"},
	{"homeos_notification", "homeos", "homeos", "一致"},
	{"homeos_refresh_token", "homeos", "homeos", "一致"},
	{"homeos_family_module", "homeos", "homeos", "一致"},
	{"homeos_outbox", "homeos", "homeos", "一致（运行表）"},
	{"homeos_idempotency", "homeos", "homeos", "一致（运行表）"},
	{"homeos_due_registration", "homeos", "calendar", "★ 不一致"},
	{"homeos_calendar_event", "homeos", "calendar", "★ 不一致"},
	{"homeos_todo", "homeos", "calendar", "★ 不一致"},
	{"homeos_reminder", "homeos", "calendar", "★ 不一致"},
	{"homeos_change_log", "homeos", "homeos", "一致（运行表）"},
	{"homeos_event_dedupe", "homeos", "homeos", "一致（运行表）"},
}

var afterTables = []TableCard{
	{"homeos_family", "homeos", "homeos", "一致"},
	{"homeos_member", "homeos", "homeos", "一致"},
	{"homeos_role", "homeos", "homeos", "一致"},
	{"homeos_permission", "homeos", "homeos", "一致"},
	{"homeos_notification", "homeos", "homeos", "一致"},
	{"homeos_refresh_token", "homeos", "homeos", "一致"},
	{"homeos_family_module", "homeos", "homeos", "一致"},
	{"homeos_outbox", "homeos", "homeos", "一致（运行表）"},
	{"homeos_idempotency", "homeos", "homeos", "一致（运行表）"},
	{"homeos_change_log", "homeos", "homeos", "一致（运行表）"},
	{"homeos_event_dedupe", "homeos", "homeos", "一致（运行表）"},
	{"calendar_event", "calendar", "calendar", "一致"},
	{"calendar_todo", "calendar", "calendar", "一致"},
	{"calendar_reminder", "calendar", "calendar", "一致"},
	{"calendar_due_registration", "calendar", "calendar", "一致（运行表）"},
}

// ---- 门禁本体：规则是「表名去掉服务前缀后，剩余部分必须属于该服务的词表」----
type Registry struct {
	// code -> 该服务允许承载的业务对象名
	Objects map[string]map[string]bool
}

var registry = Registry{
	Objects: map[string]map[string]bool{
		"homeos": {
			"homeos_family": true, "homeos_member": true, "homeos_role": true, "homeos_permission": true,
			"homeos_notification": true, "homeos_refresh_token": true, "homeos_family_module": true,
			// 运行表族
			"homeos_outbox": true, "homeos_idempotency": true, "homeos_change_log": true, "homeos_event_dedupe": true,
		},
		"calendar": {
			"calendar_event": true, "calendar_todo": true, "calendar_reminder": true,
			"calendar_due_registration": true,
		},
	},
}

// 门禁检查：给一张表，返回 (通过?, 说明)
func (r Registry) check(t TableCard) (bool, string) {
	// ① 表名必须以某个 code_ 前缀开头 —— 这一步只认字符串，不认意图
	var code string
	found := false
	for c := range r.Objects {
		if strings.HasPrefix(t.Table, c+"_") {
			code = c
			found = true
			break
		}
	}
	if !found {
		return false, "表名没有已知服务的 code 前缀"
	}
	// ② 整张表名必须在该 code 的登记词表里
	if r.Objects[code][t.Table] {
		return true, "归属一致"
	}
	rest := strings.TrimPrefix(t.Table, code+"_")
	return false, fmt.Sprintf("前缀说是 %s，但 %q 不在 %s 的登记词表里", code, rest, code)
}

// ---- 四个维度的打分器 ----
type Dimension struct {
	Name    string
	Before  string // 寄生在 HomeOS 的后果
	After   string // 独立后
	Score   int    // 1 = 说得清，0 = 说不清
	CanTell bool
}

var dimensions = []Dimension{
	{
		Name: "职责（故障域）", Score: 1, CanTell: true,
		Before: "连接与到期触发混在一个进程",
		After:  "到期扫描崩了，登录、权限、通知照常 —— 两个进程各自重启",
	},
	{
		Name: "schema 归属", Score: 1, CanTell: true,
		Before: "时间表挤在 homeos_ 前缀里，14 张表混 3 张，归属靠人记",
		After:  "calendar_ 前缀 + 独立 schema，一眼可查",
	},
	{
		Name: "迁移序列", Score: 1, CanTell: true,
		Before: "三方共用一条序列，改动互相卡，回滚会连带回滚别人的表",
		After:  "各自一条序列，可独立回滚",
	},
	{
		Name: "门禁可描述性", Score: 1, CanTell: true,
		Before: "没有 code，门禁只能说「表名以 homeos_ 开头」，无法判断业务归属",
		After:  "一个 code 决定七处命名，门禁可以逐条断言",
	},
}

func main() {
	fmt.Println("=== W28 d2 · 它为什么被抽离出来 ===")
	fmt.Println()

	// ---------- 1. 核心论点 ----------
	fmt.Println("=== 1. 核心论点：横切能力没有自己的 code，就无法被门禁如实描述 ===")
	fmt.Println()
	fmt.Println("  「门禁」在这里指 CI 里的机械校验 —— 它只认字符串，不认你的意图。")
	fmt.Println("  它要回答的问题是：「这张表属于哪个服务？」")
	fmt.Println("  答案必须能从表名里机械推出来，否则门禁无从下手。")
	fmt.Println()
	fmt.Println("  抽离前：homeos_calendar_event 的表名前缀是 homeos，")
	fmt.Println("           门禁只能答「它是 homeos 的」。但它业务上属于时间系统。")
	fmt.Println("           代码上的归属与业务上的归属不一致 → 门禁如实报错，报不出真相。")
	fmt.Println()

	// ---------- 2. 门禁跑在抽离前 ----------
	fmt.Println("=== 2. 门禁跑在「抽离前」的表清单上 ===")
	fmt.Println()
	fmt.Printf("  %s %s %s %s\n", pad("表名", 30), pad("前缀声明", 12), pad("业务归属", 12), "门禁结果")
	fmt.Println("  " + strings.Repeat("-", 92))
	beforePass, beforeFail := 0, 0
	var failures []TableCard
	for _, t := range beforeTables {
		ok, msg := registry.check(t)
		mark := "✅ " + msg
		if !ok {
			mark = "❌ " + msg
			beforeFail++
			failures = append(failures, t)
		} else {
			beforePass++
		}
		fmt.Printf("  %s %s %s %s\n", pad(t.Table, 30), pad(t.Declared, 12), pad(t.Business, 12), mark)
	}
	fmt.Println()
	fmt.Printf("  门禁结果：%d 通过 / %d 报错（共 %d 张表）\n", beforePass, beforeFail, len(beforeTables))
	fmt.Println()

	if beforeFail > 0 {
		fmt.Println("  报错的表恰好就是时间系统的四张表：")
		for _, f := range failures {
			ok, msg := registry.check(f)
			_ = ok
			fmt.Printf("    %-30s %s\n", f.Table, msg)
		}
		fmt.Println()
		fmt.Println("  这就是「说不清」的具体形态：门禁红了，但它说不清是哪里不对，")
		fmt.Println("  因为「业务归属」这一列根本不在代码里 —— 门禁只能看到前缀。")
		fmt.Println()
	}

	// ---------- 3. 加一个 code ----------
	fmt.Println("=== 3. 抽离：给横切能力一个自己的 code = calendar ===")
	fmt.Println()
	fmt.Println("  做了四件事：")
	fmt.Println("    ① 建 schema calendar，表前缀 homeos_ → calendar_")
	fmt.Println("    ② 路由从 /api/homeos/* 换到 /api/calendar/*")
	fmt.Println("    ③ 事件前缀从 homeos.* 换到 calendar.*")
	fmt.Println("    ④ 迁移文件挪到 migrations/calendar/，起自己的序列")
	fmt.Println()
	fmt.Println("  注意：没有新建任何一张表，也没有新增任何字段。")
	fmt.Println("        这是「改名不新建表」—— W29 的 d10 会专门讲这件事。")
	fmt.Println()

