	{"注册去重", "到期触发", "calendar"},
}

func blastRadius(parasitic bool) (alive, dead []string) {
	crashDomain := "homeos"
	if !parasitic {
		crashDomain = "calendar"
	}
	for _, c := range caps {
		domain := c.Domain
		if parasitic {
			domain = "homeos" // 全部挤在 homeos 进程
		}
		if domain == crashDomain {
			dead = append(dead, c.Name)
		} else {
			alive = append(alive, c.Name)
		}
	}
	return alive, dead
}

