// 门禁的机械动作：取文件名第一个下划线前缀，当作「文件声称的归属」
func claimedDomain(m Migration) string {
	return strings.SplitN(m.File, "_", 2)[0]
}

func gateReport(ms []Migration) (right, wrong int, lines []string) {
	for _, m := range ms {
		c := claimedDomain(m)
		if c == m.Domain {
			right++
			lines = append(lines, fmt.Sprintf("      %-32s 声称 %-10s 实际 %-10s ✅", m.File, c, m.Domain))
		} else {
			wrong++
			lines = append(lines, fmt.Sprintf("      %-32s 声称 %-10s 实际 %-10s ❌", m.File, c, m.Domain))
		}
	}
	return right, wrong, lines
}

