// =====================================================================
// W28 d4：七类命名域 —— 一个 code 决定七处命名。
//
// 这张卡的重点不是背表格，而是**能默写出 calendar 这一列的七个值**。
// 所以本程序做三件事：
//   ① 用一个函数把 code 派生成七处命名（证明它们真的同源，不是巧合）
//   ② 跑一个命名门禁，逐处断言七处一致，并打印 registry 的三个 code
//   ③ 遮住七个值做「默写测验」，程序自己判卷
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// ① 派生：一个 code → 七处命名
// =====================================================================

// SevenNames 是一个 code 派生的七处命名
type SevenNames struct {
	Service   string // 服务
	Schema    string // schema
	Route     string // 路由
	EventPfx  string // 事件前缀
	TablePfx  string // 表前缀
	Subpkg    string // 前端分包
	Migration string // 迁移文件
}

// Derive 是本文件的核心：一个 code 进，七处命名出。
func Derive(code string, subpkgInMain bool) SevenNames {
	return SevenNames{
		Service:   "svc-" + code,
		Schema:    code,
		Route:     "/api/" + code + "/*",
		EventPfx:  code + ".",
		TablePfx:  code + "_",
		Subpkg:    subpkgLabel(code, subpkgInMain),
		Migration: code + "_{seq}_{desc}",
	}
}

func subpkgLabel(code string, inMain bool) string {
	if inMain {
		return "主包内（不建分包）"
	}
	return "pages/" + code
}

var codes = []string{"homeos", "calendar", "finance"}

// 哪些 code 的页面在主包内
var inMainPkg = map[string]bool{"homeos": true, "calendar": true, "finance": false}

func main() {
	fmt.Println("=== W28 d4 · 七类命名域：一个 code 决定七处命名 ===")
	fmt.Println()

	// ---------------- 1. 派生 ----------------
	fmt.Println("=== 1. 派生：一个 code 进，七处命名出 ===")
	fmt.Println()
	fmt.Println("  Derive(\"calendar\") 的返回值逐项打印：")
	cal := Derive("calendar", true)
	slots := []struct {
		Name  string
		Value string
	}{
		{"服务", cal.Service},
		{"schema", cal.Schema},
		{"路由", cal.Route},
		{"事件前缀", cal.EventPfx},
		{"表前缀", cal.TablePfx},
		{"前端分包", cal.Subpkg},
		{"迁移文件", cal.Migration},
