// =====================================================================
// W28 d5：建第二个服务 —— cmd/svc-calendar/main.go 起得来、独立启停。
//
// 这是 M4 里程碑的第一天。今天不写业务逻辑，只做「进程骨架」：
//   ① 两个进程各起一个真实的 HTTP 监听器（真 listen，真发请求）
//   ② 每个进程有自己的 schema 名、自己的路由域、自己的健康检查
//   ③ 停掉其中一个，另一个照常服务（独立启停的实证）
//
// 关键：这里用 net/http + net.Listen 真起服务，不依赖 gin，
// 因为今天要证明的是「两个进程能同时活着」，不是框架用法。
// 端口用固定端口（18081 / 18082），输出完全确定。
// =====================================================================

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// 一个服务的最小骨架：配置 → 路由 → 监听
// 它刻意不 import 任何业务包 —— 这就是 tech-plan §3.2 的依赖红线。
// =====================================================================

// Config 是环境变量 → 结构体的映射（S0/S1 讲过的模式）
type Config struct {
	Code    string // 服务 code
	Schema  string // 自己的 schema
	Route   string // 自己的路由域
	Addr    string // 监听地址
	DBUser  string // 自己的数据库账号（每服务一个）
	EventPf string // 自己的事件前缀
}

func LoadConfig(code, addr string) Config {
	// 生产里从环境变量读；这里写死是为了输出确定
	switch code {
	case "homeos":
		return Config{
			Code: "homeos", Schema: "homeos", Route: "/api/homeos/*",
			Addr: addr, DBUser: "svc_homeos", EventPf: "homeos.",
		}
	case "calendar":
		return Config{
			Code: "calendar", Schema: "calendar", Route: "/api/calendar/*",
			Addr: addr, DBUser: "svc_calendar", EventPf: "calendar.",
		}
	}
	panic("unknown code: " + code)
}

// NewRouter 装路由。注意每个服务只注册自己的路由域。
func NewRouter(cfg Config) *http.ServeMux {
	mux := http.NewServeMux()

	// 健康检查：路径不带域，因为 Nginx 与 k8s 探针都打这里
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{
			"status": "ok",
			"code":   cfg.Code,
		})
	})

	// 自述接口：把七处命名里的六处打印出来（服务内可见的六处，前端那处在 d28 讲）
	mux.HandleFunc("/self", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{
			"code":         cfg.Code,
			"schema":       cfg.Schema,
			"route":        cfg.Route,
			"event_prefix": cfg.EventPf,
			"table_prefix": cfg.Code + "_",
			"db_user":      cfg.DBUser,
		})
	})

	if cfg.Code == "homeos" {
		// HomeOS 的两条占位路由（真实实现见 S4/S5）
		mux.HandleFunc("/api/homeos/auth/me", func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{
				"code": 0, "message": "ok",
				"data": map[string]any{"member_id": "mem_zhangwei", "role": "owner"},
			})
		})
		mux.HandleFunc("/api/homeos/home/summary", func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{
				"code": 0, "message": "ok",
				// due_today 的数据源是 calendar 的只读接口（16.3）
				"data": map[string]any{
					"due_today": map[string]any{
						"state": "ok",
						"from":  "calendar",
					},
				},
			})
		})
	}

	if cfg.Code == "calendar" {
		// Calendar 的三条占位路由（真实实现见 W30）
		mux.HandleFunc("/api/calendar/events", func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{
				"code": 0, "message": "ok",
				"data": map[string]any{
					"view":  r.URL.Query().Get("view"),
					"items": []any{},
				},
			})
		})
		mux.HandleFunc("/api/calendar/todos", func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"code": 0, "message": "ok", "data": map[string]any{"items": []any{}}})
		})
		mux.HandleFunc("/api/calendar/reminders", func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"code": 0, "message": "ok", "data": map[string]any{"items": []any{}}})
		})
	}

	return mux
}

func writeJSON(w http.ResponseWriter, status int, body map[string]any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

// Serve 真起一个监听器
func Serve(cfg Config) (*http.Server, net.Listener, error) {
	ln, err := net.Listen("tcp", cfg.Addr)
	if err != nil {
		return nil, nil, err
	}
	srv := &http.Server{Handler: NewRouter(cfg)}
	go func() { _ = srv.Serve(ln) }()
	return srv, ln, nil
}

// get 发一个真实的 HTTP 请求
func get(url string) (int, string, error) {
	client := &http.Client{Timeout: 2 * time.Second}
	resp, err := client.Get(url)
	if err != nil {
		return 0, "", err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	return resp.StatusCode, strings.TrimRight(string(b), "\n"), err
}

// 探针结果
type Probe struct {
	URL    string
	Status int
	Body   string
	Err    string
}

func probe(url string) Probe {
	code, body, err := get(url)
	p := Probe{URL: url, Status: code, Body: body}
	if err != nil {
		p.Err = err.Error()
	}
	return p
}

