		fmt.Printf("  %s\n", r.Body)
	}
	fmt.Println()
	fmt.Println("  due_today 的数据源不是 homeos 自己的表，而是 calendar 的")
	fmt.Println("  GET /api/calendar/events。这条只读调用有三个硬约束（16.3）：")
	fmt.Println("    超时 ≤300ms、重试 ≤1 次、失败即降级为「暂不可用 + 保留到期入口」。")
	fmt.Println("  今天先只把链路画出来，W30 d13 会真做这份聚合。")
	fmt.Println()

	// ---------------- 7. 独立启停 ----------------
	fmt.Println("=== 7. 独立启停：停掉 svc-calendar，看 homeos 会怎样 ===")
	fmt.Println()

	// 停 calendar
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	_ = servers["calendar"].Shutdown(ctx)
	cancel()
	_ = listeners["calendar"].Close()
	fmt.Println("  [STOP] svc-calendar 已优雅关闭（Shutdown + Close）")
	fmt.Println()

	time.Sleep(100 * time.Millisecond)

	// calendar 不可达
	rc := probe("http://127.0.0.1:18082/healthz")
	fmt.Printf("  svc-calendar /healthz  →  %s\n", errText(rc))
	fmt.Println("  按 PRD 3.9.7 的降级词例外：calendar 恒启用恒出生，")
	fmt.Println("  不可达时**只记「暂不可用」**，不得误判为「未启用」或「即将上线」。")
	fmt.Println()

	// homeos 照常
	rh := probe("http://127.0.0.1:18081/healthz")
	rs := probe("http://127.0.0.1:18081/api/homeos/home/summary")
	fmt.Printf("  svc-homeos  /healthz            →  状态 %d %s\n", rh.Status, rh.Body)
	if rs.Err == "" {
		fmt.Printf("  svc-homeos  /api/homeos/home/summary →  状态 %d（仍可用）\n", rs.Status)
	}
	fmt.Println()
	fmt.Println("  这就是 d3 实验 1 的实测版：到期系统挂了，登录与聚合照常。")
	fmt.Println("  如果两者还在一个进程里，这一行会变成 connection refused。")
	fmt.Println()

	// ---------------- 8. 重新拉起 ----------------
	fmt.Println("=== 8. 再把 svc-calendar 拉起来（独立启停的另一半）===")
	fmt.Println()
	cfgs2 := LoadConfig("calendar", "127.0.0.1:18082")
	srv2, ln2, err := Serve(cfgs2)
	if err != nil {
		fmt.Printf("  [FAIL] %v\n", err)
		os.Exit(1)
	}
	servers["calendar"] = srv2
	listeners["calendar"] = ln2
	fmt.Printf("  [ OK ] svc-calendar 重新监听 %s\n", ln2.Addr())
	rc2 := probe("http://127.0.0.1:18082/healthz")
	fmt.Printf("  /healthz → 状态 %d %s\n", rc2.Status, rc2.Body)
	fmt.Println()
	fmt.Println("  ⚠ tech-plan §7.7 的一条硬要求：恢复后**不得补发风暴**。")
	fmt.Println("    停机期间积压的到期项，不能一恢复就全部触发。")
	fmt.Println("    正确做法是按原定时间窗逐条触发，并给触发时刻打上「补发」标记。")
	fmt.Println()

	// ---------------- 9. 收尾 ----------------
	for code, srv := range servers {
		c, cancel2 := context.WithTimeout(context.Background(), 2*time.Second)
		_ = srv.Shutdown(c)
		cancel2()
		_ = listeners[code].Close()
	}
	fmt.Println("=== 9. 收尾 ===")
	fmt.Println("  两个服务都已优雅关闭。本程序的真实产出不是这几行输出，")
	fmt.Println("  而是这三个文件：")
	fmt.Println("    server/cmd/svc-homeos/main.go     —— 已有，S4 建好")
	fmt.Println("    server/cmd/svc-calendar/main.go    —— 今天建")
	fmt.Println("    deploy/docker-compose.yml           —— 第二个服务加进去")
	fmt.Println()
	fmt.Println("  cmd 包只做装配，不写业务逻辑（tech-plan §3.1）。")
	fmt.Println("  两个 main.go 的差别应该只有：LoadConfig 的 code 不同。")
}

type probeRow struct {
	name string
	URL  string
}

func errText(p Probe) string {
	if p.Err == "" {
		return fmt.Sprintf("状态 %d %s", p.Status, p.Body)
	}
	return "连接失败（" + shortErr(p.Err) + "）"
}

func shortErr(e string) string {
	// net/http 的错误字符串很长，只取首个逗号前的部分，保证输出稳定
	if i := strings.Index(e, ": "); i > 0 {
		return e[:i]
	}
	return e
}

// =====================================================================
// W28 d6：W28 收口 —— 两个服务同时跑 + 阶段自查。
//
// 前五天讲了「为什么独立」与「怎么建起来」。今天做两件事：
//   ① 把两个服务真的一起跑，打一张「同时跑」的全景矩阵
//   ② 跑 W28 的阶段自查器，逐条断言 10 项，通过 / 失败都打印出来
//
// 自查器有一个刻意的设计：**第 11 项故意失败**。
// 一个永远全绿的检查和一个不检查是一样的（S3 d21 的教训）。
// =====================================================================

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// 两个服务的骨架（与 d5 同构，但今天要跑全景矩阵与自查）
// =====================================================================

type Service struct {
	Code      string
	Schema    string
	Route     string
	EventPf   string
	DBUser    string
	Addr      string
	Migration string
	SubPkg    string
}

// Registry 就是 16.1 的面目录登记表
var registry = []Service{
	{
		Code: "homeos", Schema: "homeos", Route: "/api/homeos/*",
		EventPf: "homeos.", DBUser: "svc_homeos", Addr: "127.0.0.1:18091",
		Migration: "homeos_{seq}_{desc}", SubPkg: "主包内",
	},
	{
		Code: "calendar", Schema: "calendar", Route: "/api/calendar/*",
		EventPf: "calendar.", DBUser: "svc_calendar", Addr: "127.0.0.1:18092",
		Migration: "calendar_{seq}_{desc}", SubPkg: "主包内",
	},
}

func newMux(s Service) *http.ServeMux {
	mux := http.NewServeMux()

	// 两个系统级面的公共路由：健康检查与自述（不带域，探针与 Nginx 都打这里）
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok", "code": s.Code})
	})
	mux.HandleFunc("/self", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{
			"code": s.Code, "schema": s.Schema, "route": s.Route,
			"event_prefix": s.EventPf, "table_prefix": s.Code + "_",
			"db_user": s.DBUser, "migration": s.Migration,
		})
	})

	// ⚠ 关键：每个服务**只注册自己路由域下**的路径。
	//   这一行是「域隔离」的全部实现 —— 没注册就是 404，不存在「转发」这回事。
	switch s.Code {
	case "homeos":
		mux.HandleFunc("/api/homeos/auth/me", jsonHandler(map[string]any{
			"code": 0, "message": "ok", "data": map[string]any{"role": "owner"},
		}))
		mux.HandleFunc("/api/homeos/families/current", jsonHandler(map[string]any{
			"code": 0, "message": "ok",
			"data": map[string]any{
				"name": "张家", "timezone": "Asia/Shanghai", "currency": "CNY",
				// 两个系统级面不写 family_module ——「无行即未启用」只对业务面成立
				"modules": []any{"homeos", "calendar"},
			},
		}))
		mux.HandleFunc("/api/homeos/home/summary", jsonHandler(map[string]any{
			"code": 0, "message": "ok",
			"data": map[string]any{
				"due_today": map[string]any{"state": "ok", "source": "calendar", "count": 3},
				"finance":   map[string]any{"state": "ok"},
			},
		}))
		mux.HandleFunc("/api/homeos/notifications", jsonHandler(map[string]any{
			"code": 0, "message": "ok", "data": map[string]any{"unread": 5, "capped": false},
		}))
		mux.HandleFunc("/api/homeos/members", jsonHandler(map[string]any{
			"code": 0, "message": "ok", "data": map[string]any{"items": []any{}},
		}))
		// 注意：这里**没有** /api/calendar/* 的任何一条
	case "calendar":
		mux.HandleFunc("/api/calendar/events", jsonHandler(map[string]any{
			"code": 0, "message": "ok",
			"data": map[string]any{"view": "day", "items": []any{}},
		}))
		mux.HandleFunc("/api/calendar/todos", jsonHandler(map[string]any{
			"code": 0, "message": "ok", "data": map[string]any{"items": []any{}},
		}))
		mux.HandleFunc("/api/calendar/reminders", jsonHandler(map[string]any{
			"code": 0, "message": "ok", "data": map[string]any{"items": []any{}},
		}))
		// 注意：这里**没有** /api/homeos/* 的任何一条
	}
	return mux
}

func jsonHandler(body map[string]any) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(body)
	}
}

type Running struct {
	Svc  Service
	Srv  *http.Server
	Ln   net.Listener
	Base string
}

func start(s Service) (*Running, error) {
	ln, err := net.Listen("tcp", s.Addr)
	if err != nil {
		return nil, err
	}
	srv := &http.Server{Handler: newMux(s)}
	go func() { _ = srv.Serve(ln) }()
	return &Running{Svc: s, Srv: srv, Ln: ln, Base: "http://" + s.Addr}, nil
}

func (r *Running) stop() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	_ = r.Srv.Shutdown(ctx)
	_ = r.Ln.Close()
}

func (r *Running) hit(path string) (int, string) {
	client := &http.Client{Timeout: 2 * time.Second}
	resp, err := client.Get(r.Base + path)
	if err != nil {
		return 0, "ERR:" + firstSeg(err.Error())
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, strings.TrimRight(string(b), "\n")
}

func firstSeg(e string) string {
	if i := strings.Index(e, ": "); i > 0 {
		return e[:i]
	}
	return e
}

