		}
		fmt.Printf("  %s %s %s %s %s\n",
			pad(c.ID, 9), pad(c.Desc, 36), pad(c.Want, 26), pad(c.Got, 34), mark)
	}
	fmt.Println()
	fmt.Printf("  W28 自查结果：%d/%d 通过\n", passN, len(checks))
	fmt.Println()

	// ---------------- 5. 故意失败一项 ----------------
	fmt.Println("=== 5. 故意失败一项：证明这个自查器不是摆设 ===")
	fmt.Println()
	fmt.Println("  现在假设有人「图省事」，把 calendar 的路由域写成 /api/homeos/*。")
	broken := map[string]string{
		"code": "calendar", "schema": "calendar", "route": "/api/homeos/*",
		"event_prefix": "calendar.", "table_prefix": "calendar_",
		"db_user": "svc_calendar", "migration": "calendar_{seq}_{desc}",
	}
	fmt.Println()
	fmt.Printf("  %s %s %s %s %s\n", pad("编号", 9), pad("检查项", 36), pad("期望", 26), pad("实际", 34), "结果")
	fmt.Println("  " + strings.Repeat("-", 112))
	for _, c := range checks {
		got := c.Got
		pass := c.Pass
		if c.ID == "W28-4" {
			got = broken["route"]
			pass = strings.Contains(got, "/api/calendar/")
		}
		mark := "FAIL"
		if pass {
			mark = "PASS"
		}
		fmt.Printf("  %s %s %s %s %s\n",
			pad(c.ID, 9), pad(c.Desc, 40), pad(c.Want, 26), pad(got, 30), mark)
	}
	fmt.Println()
	fmt.Println("  只有 W28-4 变红。这正是它该做的：")
	fmt.Println("    一个永远全绿的自查器，和没有自查器是同一个东西（S3 d21 的教训）。")
	fmt.Println("    真正的证据是「故意弄坏一次，它会红」。")
	fmt.Println()

	// ---------------- 6. 收尾 ----------------
