}

func statusCell(code int) string {
	if code == 0 {
		return "ERR"
	}
	return fmt.Sprint(code)
}

// =====================================================================
// W29 d7：CalendarEvent 设计与 DDL —— 为什么要有 visibility。
//
// 本机没有 Postgres，所以本文件做两件事：
//   ① 给出完整可执行的 DDL（真起库后直接跑）
//   ② 用内存 slice 模拟这张表，真跑一遍「三个视图怎么读它」
//
// 今天的主线问题只有一个：**visibility 这个字段解决什么？**
//
// 场景：妈妈在日历上建了「女儿下周三的钢琴课」，爸爸能看到吗？
//   全部 visibility = family   → 爸爸看得到（默认）
//   全部 visibility = private  → 爸爸看不到（但这不是默认值）
//   混合                       → 每个人看到的条目数不同
// 也就是说 visibility 不是「谁可见」的开关，而是**把「家庭共享日历」
// 和「某个人的私人事项」放进同一张表**的手段。
