// =====================================================================
// 可见性过滤：这是 visibility 存在的全部意义
// =====================================================================

func visibleTo(e Event, memberID string) bool {
	switch e.Vis {
	case VisFamily:
		// 全家庭可见。空 members 也算 family 可见 —— 它就是「全家的日历」
		return true
	case VisMembers:
		// 只有 members 里的人在列表里
		for _, m := range e.Members {
			if m == memberID {
				return true
			}
		}
		return false
	case VisPrivate:
		// 私人：创建者自己可见。今天的模型用 members[0] 代表创建者
		return len(e.Members) > 0 && e.Members[0] == memberID
	}
	return false
}

// 越权检查：不是 family 的事件一律不可见（S3 d18/d19）
func visibleInFamily(e Event, famID string) bool {
	return e.FamilyID == famID
}

