// =====================================================================
// W29 d8：Todo 设计与 DDL —— done_returns_to 是什么、为什么它重要。
//
// 主线问题：**在到期中心点「完成」，业务面的对象怎么跟着完成？**
//
// 场景：finance 有一张待还的信用卡账单，due_at = 03-20。
//   calendar 里有一条 calendar_todo 写着「还信用卡」。
//   用户在日历页点了「完成」。
//   此时 —— finance.finance_bill.status 还应该是 unpaid 吗？
//
// 如果是，那首页财务格会一直显示「有 3 张待还账单」，用户已经还了。
// PRD 16.2 的口径是：**权威数据仍在业务面**，calendar 只持有到期登记与完成回写。
// 所以完成动作必须有一条**回写路径**，而 done_returns_to 就是这条路径的地址。
//
// 本文件给出完整 DDL，并真跑一遍「完成 → 回写 → 状态变化」。
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

