// =====================================================================
// 完成回写：解析 done_returns_to，然后改业务对象
// =====================================================================

type ReturnsTo struct {
	System      string
	SourceID    string
	Field       string
	TargetValue string
	Valid       bool
	Note        string
}

func ParseReturns(s string) ReturnsTo {
	if s == "" {
		return ReturnsTo{Note: "空 —— 不需要回写（纯 calendar 自持的待办）"}
	}
	parts := strings.Split(s, ":")
	if len(parts) != 4 {
		return ReturnsTo{Note: "格式错误：应为四段，实得 " + fmt.Sprint(len(parts)) + " 段"}
	}
	return ReturnsTo{
		System: parts[0], SourceID: parts[1], Field: parts[2], TargetValue: parts[3],
		Valid: true,
	}
}

// 回写：改业务对象
func applyWriteback(rt ReturnsTo) string {
	if rt.Note != "" {
		return "跳过回写：" + rt.Note
	}
	// 本程序只模拟 finance 的两张单据
	var target *Bill
	switch rt.SourceID {
	case bill.ID:
		target = &bill
	case financeRecurring.ID:
		target = &financeRecurring
	default:
		return fmt.Sprintf("找不到来源对象 %s —— 孤儿引用，进每日对账", rt.SourceID)
	}
	switch rt.Field {
	case "status":
		target.Status = rt.TargetValue
		return fmt.Sprintf("%s.status: %s → %s", rt.SourceID, "unpaid", rt.TargetValue)
	case "settled_cents":
		return fmt.Sprintf("%s.settled_cents → 从 finance 侧真实单据取值", rt.SourceID)
	default:
		return fmt.Sprintf("未知字段 %s —— 回写失败，缺陷", rt.Field)
	}
}

// Complete 完成一条待办，返回 (是否成功, 事件载荷, 说明)
func Complete(id string, at time.Time) (bool, string, string) {
	for i := range todos {
		if todos[i].ID != id {
			continue
		}
		if todos[i].Status == "done" {
			return false, "", "已经是 done 状态，重复完成（version 不匹配应返 409）"
		}
		todos[i].Status = "done"
		atCopy := at
		todos[i].DoneAt = &atCopy

		rt := ParseReturns(todos[i].DoneReturns)
		wb := applyWriteback(rt)

		// 事件信封（13 字段，S4/W30 讲过）：幂等键 = event_type + business_id
		env := map[string]any{
			"event_id":    "evt_gen_" + id,
			"type":        "calendar.todo.completed",
			"source":      "calendar",
			"business_id": id,
			"family_id":   todos[i].FamilyID,
			"member_id":   todos[i].MemberID,
			"payload": map[string]any{
				"source_system":   todos[i].SourceSys,
				"source_id":       todos[i].SourceID,
				"done_returns_to": todos[i].DoneReturns,
			},
			"version":         "1.0",
			"created_at":      at.Format(time.RFC3339),
			"idempotency_key": "calendar.todo.completed:" + id,
			"causation_id":    nil,
			"attempt":         0,
			"delivery":        "stream",
		}
		b, _ := json.MarshalIndent(env, "  ", "  ")
		return true, string(b), wb
	}
	return false, "", "找不到这条待办"
}

