//
// PRD 只给了 owner_id，所以应用层唯一的过滤手段是：
//     WHERE owner_id = ?
// 这条 SQL **不带 family_id** —— 因为表里没有这一列。
// =====================================================================

func listRemindersV0(ownerID string) []ReminderV0 {
	var out []ReminderV0
	for _, r := range remindersV0 {
		if r.OwnerID == ownerID {
			out = append(out, r)
		}
	}
	return out
}

// 但真正的问题是：**trigger_at 的到期扫描**（每分钟跑的那条）
func dueScanV0(now time.Time) []ReminderV0 {
	var out []ReminderV0
	for _, r := range remindersV0 {
		if r.Status != "active" || r.NextAt == nil {
			continue
		}
		if !r.NextAt.After(now) {
			out = append(out, r)
		}
	}
	return out
}

// =====================================================================
// 查询二：修好版 —— 加了 family_id 之后
// =====================================================================

var remindersV1 []ReminderV1

func initV1() {
	// 把 V0 的数据补上 family_id。映射关系来自「owner_id 属于哪个家庭」
	owner2fam := map[string]string{}
	for _, f := range families {
		for _, u := range f.Users {
			owner2fam[u] = f.ID
		}
		for _, k := range f.Kids {
			owner2fam[k] = f.ID
		}
	}
	for _, r := range remindersV0 {
		remindersV1 = append(remindersV1, ReminderV1{ReminderV0: r, FamilyID: owner2fam[r.OwnerID]})
	}
}

func listRemindersV1(familyID, ownerID string) []ReminderV1 {
	var out []ReminderV1
	for _, r := range remindersV1 {
		if r.FamilyID == familyID && r.OwnerID == ownerID {
			out = append(out, r)
		}
	}
	return out
}

func dueScanV1(familyID string, now time.Time) []ReminderV1 {
	var out []ReminderV1
	for _, r := range remindersV1 {
		if r.FamilyID != familyID || r.Status != "active" || r.NextAt == nil {
			continue
		}
		if !r.NextAt.After(now) {
			out = append(out, r)
		}
	}
	return out
}

