// =====================================================================
// W29 d10：改名迁移 —— homeos_calendar_event → calendar_event。
//
// PRD 3.9.5 原文：「本次抽离不新建任何表、不新增任何字段」。
// 这句话很容易被读成「那就建个新表把数据搬过去」—— 那就是**新建表**。
//
// 今天讲清「改名不新建表」这五个字的三层意思：
//   ① 物理：同一张表，同一个 relid，用 ALTER TABLE ... RENAME
//   ② 逻辑：schema 也换了（SET SCHEMA），所以旧名字彻底消失
//   ③ 纪律：**改已执行过的迁移是错的**，新写一个改名迁移
//
// 本程序模拟一个「迁移执行器」：真的把表名与 schema 改掉，
// 逐条打印每一步的影响，并验证 id / 行数 / 索引 / 约束都没变。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// 迁移执行器：模拟 Postgres 的 catalog
// =====================================================================

type Index struct {
	Name    string
	Table   string
	Def     string
	Partial bool
}

type Table struct {
	Relid  string // Postgres 的物理标识，永不变
	Schema string
	Name   string
	Rows   int
	Cols   []string
	Idx    []Index
	Owner  string
}

type Catalog struct {
	Schemas map[string][]string // schema -> 表名列表
	Tables  map[string]*Table   // relid -> 表
}

func newCatalog() *Catalog {
	return &Catalog{Schemas: map[string][]string{}, Tables: map[string]*Table{}}
}

func (c *Catalog) add(t *Table) {
	c.Tables[t.Relid] = t
	c.Schemas[t.Schema] = append(c.Schemas[t.Schema], t.Name)
}

// 模拟 ALTER TABLE ... SET SCHEMA ... RENAME TO ...
func (c *Catalog) rename(relid, newSchema, newName string) (int, int) {
	t := c.Tables[relid]
	// 从旧 schema 列表移除
	for i, n := range c.Schemas[t.Schema] {
		if n == t.Name {
			c.Schemas[t.Schema] = append(c.Schemas[t.Schema][:i], c.Schemas[t.Schema][i+1:]...)
			break
		}
	}
	old := t.Schema + "." + t.Name
	t.Schema, t.Name = newSchema, newName
	// 索引名里的表名部分要跟着改（Postgres 会自动改，这里显式模拟）
	for i := range t.Idx {
		t.Idx[i].Table = newName
		t.Idx[i].Name = strings.Replace(t.Idx[i].Name, old[:len(old)-len(strings.Split(old, ".")[0])], newSchema+"_", 1)
	}
	c.Schemas[newSchema] = append(c.Schemas[newSchema], newName)
	return len(t.Cols), t.Rows
}

func (c *Catalog) qualified() []string {
	var out []string
	for sch, names := range c.Schemas {
		for _, n := range names {
			out = append(out, sch+"."+n)
		}
	}
	sort.Strings(out)
	return out
}

func (c *Catalog) findByPrefix(pfx string) []string {
	var out []string
	for _, q := range c.qualified() {
		if strings.Contains(q, pfx) {
			out = append(out, q)
		}
	}
	return out
}

