func q2relid(c *Catalog, qualified string) string {
	for relid, t := range c.Tables {
		if t.Schema+"."+t.Name == qualified {
			return relid
		}
	}
	return "?"
}

func countBadPrefix(c *Catalog, schema string) int {
	n := 0
	for _, name := range c.Schemas[schema] {
		if !strings.HasPrefix(name, "calendar_") {
			n++
		}
	}
	return n
}

// =====================================================================
// W29 d11：三张表的索引设计 —— 到期中心要按时间查。
//
// S3 d17 讲了列顺序规则（等值在前、范围在后），S3 d13/d14 讲了游标分页。
// 今天把这两条用到具体表上：**到期中心只有一条热路径，它必须走索引。**
//
// 热路径是什么？每分钟跑一次的到期扫描：
//     WHERE status = 'active'
//       AND family_id = ?
//       AND next_at <= now()
//       AND deleted_at IS NULL
//     ORDER BY next_at
//     LIMIT 200
//
// 本程序做三件事：
//   ① 列出 9 条接口各自的 SQL，逐条映射到索引
//   ② 写一个**索引选择器**：给定 WHERE + ORDER BY，判断会走哪个索引
//   ③ 故意设计三个「看起来对但走不上索引」的写法，用选择器判红
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// 索引模型
// =====================================================================

type Index struct {
	Name    string
	Table   string
	Cols    []string
	Partial string // 部分索引的 WHERE 条件（空 = 全表索引）
	Kind    string // "btree" / "unique-partial"
}

// 三张表全部索引（S3 d21 的口径：每张带 deleted_at 的表都配部分索引）
var indexes = []Index{
	// ---- calendar_event ----
	{Name: "calendar_event_pkey", Table: "calendar_event",
		Cols: []string{"id"}, Partial: "", Kind: "btree"}, // 主键自带
	{Name: "idx_calendar_event_family_start", Table: "calendar_event",
		Cols: []string{"family_id", "start_at"}, Partial: "deleted_at IS NULL", Kind: "btree"},
	{Name: "idx_calendar_event_family_end", Table: "calendar_event",
		Cols: []string{"family_id", "end_at"}, Partial: "deleted_at IS NULL", Kind: "btree"},
	{Name: "uniq_calendar_event_source_kind", Table: "calendar_event",
		Cols:    []string{"family_id", "source_system", "source_id", "kind"},
		Partial: "deleted_at IS NULL AND source_id IS NOT NULL", Kind: "unique-partial"},

	// ---- calendar_todo ----
	{Name: "idx_calendar_todo_family_member_due", Table: "calendar_todo",
		Cols:    []string{"family_id", "member_id", "status", "due_at"},
		Partial: "deleted_at IS NULL", Kind: "btree"},
	{Name: "idx_calendar_todo_family_creator_due", Table: "calendar_todo",
		Cols:    []string{"family_id", "creator_id", "status", "due_at"},
		Partial: "deleted_at IS NULL", Kind: "btree"},
	{Name: "idx_calendar_todo_family_archived", Table: "calendar_todo",
		Cols:    []string{"family_id", "status", "updated_at DESC"},
		Partial: "deleted_at IS NULL AND status = 'archived'", Kind: "btree"},
	{Name: "idx_calendar_todo_family_due_open", Table: "calendar_todo",
		Cols:    []string{"family_id", "due_at"},
		Partial: "deleted_at IS NULL AND status = 'open'", Kind: "btree"},
	{Name: "uniq_calendar_todo_source_kind", Table: "calendar_todo",
		Cols:    []string{"family_id", "source_system", "source_id", "kind"},
		Partial: "deleted_at IS NULL AND source_id IS NOT NULL", Kind: "unique-partial"},

	// ---- calendar_reminder ----
	{Name: "idx_calendar_reminder_family_owner_next", Table: "calendar_reminder",
		Cols:    []string{"family_id", "owner_id", "next_at"},
		Partial: "deleted_at IS NULL", Kind: "btree"},
	{Name: "idx_calendar_reminder_family_next", Table: "calendar_reminder",
		Cols:    []string{"family_id", "next_at"},
		Partial: "deleted_at IS NULL AND status = 'active'", Kind: "btree"},
	{Name: "uniq_calendar_reminder_source_kind", Table: "calendar_reminder",
		Cols:    []string{"family_id", "source_system", "source_id", "kind"},
		Partial: "deleted_at IS NULL AND source_id IS NOT NULL", Kind: "unique-partial"},
}

// =====================================================================
// 索引选择器：模拟 Postgres 的最左前缀匹配
//
// 规则（简化但足够教学用）：
//   ① WHERE 里的等值条件（col = ?）可以按索引列顺序逐个匹配
//   ② 第一个范围条件（col <= ? / col < ? / BETWEEN）可以匹配，且之后仍能做 ORDER BY
//   ③ ORDER BY 的列必须是范围条件那一列或它之后，才不用额外排序
//   ④ 部分索引的 WHERE 必须被查询条件蕴含
// =====================================================================

type Cond struct {
	Col string
	Op  string // "=" / "<=" / ">" / "BETWEEN"
}

// 可以用索引走的方向
type Plan struct {
	Index        string
	UsesFullScan bool
	SortNeeded   bool
	Note         string
	OK           bool
}

// Selector 判断一个查询能走哪个索引（取「最左前缀最长」的那个）
func Selector(table string, conds []Cond, orderBy []string, predConds []string) Plan {
	best := Plan{OK: false, Note: "无索引可用 → 全表扫描 + 排序"}
	bestMatched := -1
	bestSpecific := -1 // 已命中索引的具体程度（0=全表，1=普通部分，2=带 status）

	for _, ix := range indexes {
		if ix.Table != table {
			continue
		}
		// ① 部分索引的 WHERE 必须被查询条件蕴含
		if ix.Partial != "" && !partialCovered(ix.Partial, predConds) {
			continue
		}
		// ② 最左前缀匹配
		matched, rangeAt := matchPrefix(ix.Cols, conds)
		if matched == 0 {
			continue
		}
		// ③ 排序检查：ORDER BY 列必须在索引里，且位于「范围列」或「等值匹配末位」之后
		//    经验规则：索引 (a,b,c) 上，WHERE a=? AND c<=? ORDER BY c → 零排序
		//             WHERE a=? AND b=? AND c<=? ORDER BY c → 零排序
		//             WHERE a=? ORDER BY c      → 也零排序（b 未约束，c 仍有局部序）
		sortNeeded := true
		if len(orderBy) == 0 {
			sortNeeded = false
		} else {
			pos := idxOf(ix.Cols, orderBy[0])
			if pos < 0 {
				sortNeeded = true // 排序键根本不在索引里
			} else if rangeAt >= 0 {
				sortNeeded = pos < rangeAt
			} else {
				sortNeeded = pos < matched
			}
		}
		note := fmt.Sprintf("前 %d 列匹配", matched)
		if rangeAt >= 0 {
			note += fmt.Sprintf("，第 %d 列是范围条件", rangeAt+1)
		}
		if len(orderBy) > 0 {
			if sortNeeded {
				note += "；排序键不在索引可用位置 → 需额外排序"
			} else {
				note += "；索引天然有序 → 零排序"
			}
		}
		// 选取规则：
		//   ① 部分索引被完整蕴含（partialCovered 已保证）时，specific=1
		//   ② specific 高的优先 —— 它索引里的行更少
		//   ③ 同 specific 时取匹配列数最多的
		specific := 0
		if ix.Partial != "" {
			specific = 1
		}
		if strings.Contains(ix.Partial, "status") {
			// 带 status 条件的部分索引更具体：索引里只有一种 status
			specific = 2
		}
		better := false
		switch {
		case specific > bestSpecific:
			better = true
		case specific == bestSpecific && matched > bestMatched:
			better = true
		}
		if better {
			bestMatched = matched
			bestSpecific = specific
			best = Plan{Index: ix.Name, SortNeeded: sortNeeded, Note: note, OK: true}
		}
	}
	return best
}

func matchPrefix(cols []string, conds []Cond) (int, int) {
	matched := 0
	rangeAt := -1
	for _, c := range conds {
		if rangeAt >= 0 {
			break // 范围列之后不能再用等值匹配
		}
		if c.Op == "func" {
			// 列上套了函数 → 索引的有序性失效，不能用于匹配
			continue
		}
		// 该列是否在索引的第 matched 位
		if matched < len(cols) && strings.TrimSuffix(strings.TrimSpace(cols[matched]), " DESC") == c.Col {
			matched++
			if c.Op != "=" {
				rangeAt = matched - 1
			}
		}
	}
	return matched, rangeAt
}

// idxOf 返回列在索引里的位置；忽略 ASC/DESC 后缀。
// 索引定义里写的是 "updated_at DESC"，但 ORDER BY 写的是 "updated_at"，
// 两者指的是同一列 —— 不做这个归一化就会出现「明明有序却说要排序」。
func idxOf(cols []string, col string) int {
	for i, c := range cols {
		if base := strings.TrimSuffix(strings.TrimSpace(c), " DESC"); base == col {
			return i
		}
	}
	return -1
}

func partialCovered(partial string, queryConds []string) bool {
	// 简化：把部分索引 WHERE 里的每个条件与查询条件比对
	parts := strings.Split(partial, " AND ")
	for _, p := range parts {
		found := false
		for _, q := range queryConds {
			if strings.TrimSpace(q) == strings.TrimSpace(p) {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

