	fmt.Printf("    ORDER BY    → 正好是范围列，索引天然有序，零排序\n")
	fmt.Println()

	// ---------------- 3. 9 条接口的索引映射 ----------------
	fmt.Println("=== 3. 9 条接口的 SQL 与索引映射 ===")
	fmt.Println()
	type Q struct {
		Method string
		Path   string
		Table  string
		Conds  []Cond
		Order  []string
		Pred   []string
		Desc   string
	}
	queries := []Q{
		{"GET", "/api/calendar/events?view=day", "calendar_event",
			[]Cond{{"family_id", "="}, {"start_at", "BETWEEN"}}, []string{"start_at"},
			[]string{"deleted_at IS NULL"}, "日视图：某天的 [00:00, 24:00)"},
		{"GET", "/api/calendar/events?view=week", "calendar_event",
			[]Cond{{"family_id", "="}, {"start_at", "BETWEEN"}}, []string{"start_at"},
			[]string{"deleted_at IS NULL"}, "周视图：一周七天合并成一个时间窗"},
		{"GET", "/api/calendar/events?view=month", "calendar_event",
			[]Cond{{"family_id", "="}, {"start_at", "BETWEEN"}}, []string{"start_at"},
			[]string{"deleted_at IS NULL"}, "月视图：整月时间窗"},
		{"GET", "/api/calendar/events/{id}", "calendar_event",
			[]Cond{{"id", "="}}, nil,
			[]string{"deleted_at IS NULL"}, "主键点查，走 PK 索引"},
		{"GET", "/api/calendar/todos?scope=assigned", "calendar_todo",
			[]Cond{{"family_id", "="}, {"member_id", "="}, {"status", "="}, {"due_at", "BETWEEN"}},
			[]string{"due_at"}, []string{"deleted_at IS NULL"}, "分配给我"},
		{"GET", "/api/calendar/todos?scope=created", "calendar_todo",
			[]Cond{{"family_id", "="}, {"creator_id", "="}, {"status", "="}, {"due_at", "BETWEEN"}},
			[]string{"due_at"}, []string{"deleted_at IS NULL"}, "我创建的"},
		{"GET", "/api/calendar/todos?scope=archived", "calendar_todo",
			[]Cond{{"family_id", "="}}, []string{"updated_at"},
			[]string{"deleted_at IS NULL", "status = 'archived'"}, "已归档"},
		{"GET", "/api/calendar/reminders", "calendar_reminder",
			[]Cond{{"family_id", "="}, {"owner_id", "="}}, []string{"next_at"},
			[]string{"deleted_at IS NULL"}, "我的提醒"},
		{"（后台）到期扫描", "svc-calendar 内部", "calendar_reminder",
			[]Cond{{"family_id", "="}, {"next_at", "<="}}, []string{"next_at"},
			[]string{"deleted_at IS NULL", "status = 'active'"}, "唯一热路径"},
	}
	fmt.Printf("  %s %s %s %s %s\n", pad("方法", 12), pad("路径", 36), pad("表", 18), pad("命中索引", 44), "排序")
	fmt.Println("  " + strings.Repeat("-", 148))
	sortNeededN := 0
	for _, q := range queries {
		p := Selector(q.Table, q.Conds, q.Order, q.Pred)
		sn := yesNo(p.SortNeeded)
		if p.SortNeeded {
			sortNeededN++
		}
		fmt.Printf("  %s %s %s %s %s\n", pad(q.Method, 12), pad(q.Path, 36), pad(q.Table, 18), pad(p.Index, 44), sn)
	}
	fmt.Println()
	fmt.Printf("  %d 条查询里 %d 条需要额外排序。\n", len(queries), sortNeededN)
	if sortNeededN == 0 {
		fmt.Println("  全部零排序 —— 这是索引设计到位的标志。")
		fmt.Println("  「零排序」的意义：数据量再翻十倍，排序耗时也不变（索引已有序）。")
	} else {
		fmt.Println("  要额外排序的条目必须在卡片里写下原因，不能留到线上才发现。")
	}
	fmt.Println()

	// 逐条说明
	fmt.Println("  逐条说明：")
	fmt.Println()
	for i, q := range queries {
		p := Selector(q.Table, q.Conds, q.Order, q.Pred)
		fmt.Printf("  %d. %s %s\n", i+1, q.Method, q.Path)
		fmt.Printf("     表      %s\n", q.Table)
		fmt.Printf("     用途    %s\n", q.Desc)
		fmt.Printf("     索引    %s\n", p.Index)
		fmt.Printf("     判定    %s\n", p.Note)
		fmt.Println()
	}

	// ---------------- 4. 三个错误的写法 ----------------
	fmt.Println("=== 4. 三个「看起来对但走不上索引」的写法 ===")
	fmt.Println()
	fmt.Println("  这三个都是新手最容易写的，而且在小数据量下**完全正常**，")
	fmt.Println("  到几千行时才突然变慢 —— 这是最难查的一类性能问题。")
	fmt.Println()
	wrongs := []struct {
		Name  string
		SQL   string
		Conds []Cond
		Order []string
		Pred  []string
		Table string
		Why   string
	}{
		{
			Name:  "① 漏掉 family_id",
			SQL:   "WHERE status='active' AND next_at <= $1 AND deleted_at IS NULL\n       ORDER BY next_at LIMIT 200",
			Table: "calendar_reminder",
			Conds: []Cond{{"status", "="}, {"next_at", "<="}},
			Order: []string{"next_at"},
			Pred:  []string{"deleted_at IS NULL", "status = 'active'"},
			Why: "索引第一列是 family_id。不用它等于不用这个索引 —— " +
				"Postgres 会退化成扫 idx_calendar_reminder_family_next 的全部索引项再回表过滤，" +
				"或者直接按 next_at 全表扫。**这是 S3 d18 的老问题在时间系统上的复现。**",
		},
		{
			Name:  "② 对时间列用函数",
			SQL:   "WHERE family_id=$1\n       AND DATE(next_at) <= $2\n       AND deleted_at IS NULL",
			Table: "calendar_reminder",
			Conds: []Cond{{"family_id", "="}, {"next_at", "func"}},
			Order: []string{"next_at"},
			Pred:  []string{"deleted_at IS NULL"},
			Why: "列上套了函数，索引里的有序性就用不上了 —— " +
				"选择器只匹配到 family_id 这一列，next_at 那一列被判为不可用。" +
				"正确写法是把函数移到等号右边，或者用范围条件：" +
				"next_at >= 本月第一天 AND next_at < 下月第一天。",
		},
		{
			Name:  "③ ORDER BY 用了范围列之后的列",
			SQL:   "WHERE family_id=$1 AND member_id=$2 AND status='open'\n       ORDER BY created_at DESC",
			Table: "calendar_todo",
			Conds: []Cond{{"family_id", "="}, {"member_id", "="}, {"status", "="}, {"due_at", "BETWEEN"}},
			Order: []string{"created_at"},
			Pred:  []string{"deleted_at IS NULL"},
			Why: "索引是 (family_id, member_id, status, due_at)，" +
				"它按 due_at 有序，不按 created_at 有序。ORDER BY created_at 必须额外排序，" +
				"而且如果带了 LIMIT，Postgres 会做 top-N heapsort —— 数据量大时很贵。" +
				"要么改排序键，要么加一条按 created_at 排序的索引。",
		},
	}
	for _, w := range wrongs {
		p := Selector(w.Table, w.Conds, w.Order, w.Pred)
		fmt.Printf("  %s\n", w.Name)
		fmt.Println("     错误 SQL：")
		for _, line := range strings.Split(w.SQL, "\n") {
			fmt.Printf("       %s\n", line)
		}
		hit := p.Index
		if hit == "" {
			hit = "**无索引可用**"
		}
		fmt.Printf("     索引选择器判定：命中 %s\n", hit)
		fmt.Printf("     是否需排序  %s\n", yesNo(p.SortNeeded))
		fmt.Printf("     机理        %s\n\n", w.Why)
	}
	fmt.Println("  注意第 ①②条：选择器仍然「命中」了索引。")
	fmt.Println("  这是因为选择器只看列的顺序，不看是否套了函数。")
	fmt.Println("  真实的 Postgres 会在 EXPLAIN 里显示 `Seq Scan` 或 `Index Scan`，")
	fmt.Println("  区分方法只有一个 —— **把 SQL 贴进 EXPLAIN 看**（S3 d17 讲过）。")
	fmt.Println()

	// ---------------- 5. 为什么到期中心是 (family_id, trigger_at) ----------------
	fmt.Println("=== 5. 重点：为什么是 (family_id, next_at) 这个顺序 ===")
	fmt.Println()
	fmt.Println("  假设把顺序写成 (next_at, family_id)：")
	fmt.Println()
	fmt.Println("    WHERE family_id = $1 AND status='active' AND next_at <= $2")
	fmt.Println("                 ↑                                        ↑")
	fmt.Println("    （第 2 列，要先定位 next_at <= $2 的整个范围才能用到 family_id）")
	fmt.Println()
	fmt.Println("  后果：")
	fmt.Println()
	orders := []struct{ Order, Effect string }{
		{"(family_id, next_at)", "定位到单个租户 → 该租户内按时间走 → 扫到的行几乎全是目标行"},
		{"(next_at, family_id)", "先扫「所有租户里 next_at <= $2 的行」→ 再逐行比对 family_id"},
	}
	fmt.Printf("  %s %s\n", pad("索引列顺序", 26), "扫描行为")
	fmt.Println("  " + strings.Repeat("-", 104))
	for _, o := range orders {
		fmt.Printf("  %s %s\n", pad(o.Order, 26), o.Effect)
	}
	fmt.Println()
	fmt.Println("  量化一下。假设 100 个家庭，每家 200 条 active reminder：")
	fmt.Println()
	quant := []struct {
		Order string
		Scan  string
		Ret   string
	}{
		{"(family_id, next_at)", "扫 2 条（这家今天到期的）", "2 条"},
		{"(next_at, family_id)", "扫 400 条（所有家庭今天到期的）", "2 条有用 + 398 条白扫"},
	}
	fmt.Printf("  %s %s %s\n", pad("索引列顺序", 26), pad("扫描行数", 34), "回表行数")
	fmt.Println("  " + strings.Repeat("-", 100))
	for _, q := range quant {
		fmt.Printf("  %s %s %s\n", pad(q.Order, 26), pad(q.Scan, 34), q.Ret)
	}
	fmt.Println()
	fmt.Println("  差 200 倍。家庭数越多越糟 —— 这个缺陷会**随客户增长而恶化**。")
	fmt.Println("  这就是 S3 d17 那句「等值在前、范围在后」的全部理由。")
	fmt.Println()

	// ---------------- 6. 索引数量 ----------------
	fmt.Println("=== 6. 11 个索引是不是太多了 ===")
	fmt.Println()
	fmt.Println("  按表统计：")
	fmt.Println()
	byTable := map[string]int{}
	for _, ix := range indexes {
		byTable[ix.Table]++
	}
	tables := []string{"calendar_event", "calendar_todo", "calendar_reminder"}
	fmt.Printf("  %s %s %s\n", pad("表", 22), pad("索引数", 10), "覆盖的查询")
	fmt.Println("  " + strings.Repeat("-", 84))
	covers := map[string]string{
		"calendar_event":    "3 条（日/周/月视图走同一个，详情走 PK）",
		"calendar_todo":     "3 条列表 + 1 条到期中心聚合",
		"calendar_reminder": "1 条列表 + 1 条到期扫描 + 1 条幂等",
	}
	for _, t := range tables {
		fmt.Printf("  %s %s %s\n", pad(t, 22), pad(fmt.Sprint(byTable[t]), 10), covers[t])
	}
	fmt.Println()
	fmt.Println("  11 个索引对三张表来说是合理的，原因：")
	fmt.Println("    ① 每条接口至少一个索引 —— 9 条接口里 8 条走索引，1 条走 PK")
	fmt.Println("    ② 每个「列表视角」一个索引（分配给我 / 我创建的 / 已归档）")
	fmt.Println("    ③ 幂等键索引是唯一索引，不算冗余")
	fmt.Println("    ④ 没有「一个索引覆盖全部」的可能 —— 三个列表的排序键不同")
	fmt.Println()
	fmt.Println("  真正会变多的是：如果将来加「按标题搜」「按标签筛」，")
	fmt.Println("  每加一个筛选维度就是一个新索引。所以要设上限：")
	fmt.Println("    单表索引数 > 8 时要求写评估说明；> 12 时要求删掉一个。")
	fmt.Println("  写索引不花钱，写索引的**写放大**要钱 —— 每个索引都会拖慢 INSERT/UPDATE。")
	fmt.Println()

	// ---------------- 7. 小结 ----------------
	fmt.Println("=== 7. W29 d11 小结 ===")
	fmt.Println()
	fmt.Println("  ① 到期扫描是唯一热路径：等值(family_id, status) + 范围(next_at) + ORDER BY next_at")
	fmt.Println("  ② 所以 (family_id, next_at) 这个列顺序不能反 —— 反了差 200 倍")
	fmt.Println("  ③ 9 条接口里 8 条走索引，全部零排序")
	fmt.Println("  ④ 「分配给我 / 我创建的 / 已归档」三个列表必须三条索引（排序键不同）")
	fmt.Println("  ⑤ 唯一索引走部分索引，幂等键带 source_id IS NOT NULL")
	fmt.Println("  ⑥ 索引多不是问题，写放大才是；单表索引数设上限")
	fmt.Println()
	fmt.Println("  明天 W29 收口：三表建好 + 迁移可重放 + 阶段自查。")
}

func yesNo(b bool) string {
	if b {
		return "需要"
	}
	return "不需要"
}

