type SchemaState struct {
	Tables    map[string]int // 表名 -> 列数
	Indexes   []string
	HasRLS    map[string]bool
	Columns   map[string][]string
	HasNOTNLL map[string]bool
	Checks    []string // CHECK 约束名
}

func newState() *SchemaState {
	return &SchemaState{
		Tables:    map[string]int{},
		Indexes:   []string{},
		HasRLS:    map[string]bool{},
		Columns:   map[string][]string{},
		HasNOTNLL: map[string]bool{},
		Checks:    []string{},
	}
}

