		s.Checks = remove(s.Checks, "ck_todo_done_at_consistency")
		s.Checks = remove(s.Checks, "ck_todo_returns_shape")
		s.Checks = remove(s.Checks, "ck_todo_returns_requires_source")
	case 3:
		delete(s.HasNOTNLL, "calendar_reminder.family_id")
		delete(s.HasRLS, "calendar_reminder")
		cs := s.Columns["calendar_reminder"]
		s.Columns["calendar_reminder"] = cs[:len(cs)-1]
		s.Tables["calendar_reminder"] = 16
		s.Indexes = remove(s.Indexes, "idx_calendar_reminder_family_owner_next")
		s.Indexes = remove(s.Indexes, "idx_calendar_reminder_family_next")
		s.Indexes = append(s.Indexes, "idx_calendar_reminder_owner")
	case 2:
	case 1:
		s.Tables = map[string]int{}
		s.Indexes = nil
		s.Columns = map[string][]string{}
		s.HasRLS = map[string]bool{}
		s.HasNOTNLL = map[string]bool{}
		s.Checks = nil
	}
}

func renameIdx(in []string, from, to string) []string { return in }
func replaceOrAdd(in []string, add, _ string) []string {
	if !contains(in, add) {
		in = append(in, add)
	}
	return in
}
func remove(in []string, x string) []string {
	var out []string
	for _, v := range in {
		if v != x {
			out = append(out, v)
		}
	}
	return out
}
func contains(in []string, x string) bool {
	for _, v := range in {
		if v == x {
			return true
		}
	}
	return false
}

func (s *SchemaState) snapshot() string {
	var tbls []string
	for t := range s.Tables {
		tbls = append(tbls, t)
	}
	sortStrings(tbls)
	idx := append([]string{}, s.Indexes...)
	sortStrings(idx)
	return fmt.Sprintf("表=%d 列总数=%d 索引=%d CHECK=%d RLS=%d",
		len(s.Tables), sumCols(s.Columns), len(idx), len(s.Checks), len(s.HasRLS))
}

func sumCols(m map[string][]string) int {
	n := 0
	for _, v := range m {
		n += len(v)
	}
	return n
}

func sortStrings(s []string) {
	for i := 0; i < len(s); i++ {
		for j := i + 1; j < len(s); j++ {
			if s[j] < s[i] {
				s[i], s[j] = s[j], s[i]
			}
		}
	}
}

