// =====================================================================
// W30 d13：到期中心的读接口设计 —— view=day|week|month 三视图。
//
// ★ 本卡片的核心：**日/周/月不是三份数据，是同一份数据的三次切片。**
//
// PRD 3.9.6 的 GET /api/calendar/events 只有一条接口，
// 带一个 view 参数取 day|week|month。
//
// 这意味着：
//   · 数据表只有一张 calendar_event（没有 calendar_event_daily 表）
//   · 三种视图的区别只在「时间窗怎么算」
//   · 服务端要为客户端算好三视图各自的元数据（网格、统计）
//
// 本程序用内存模拟真算一遍：造 12 条事件，跑出三个视图各自的结果，
// 证明它们确实是同一份数据的不同切片。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)

// 基准日：2026-03-18 周三
var base = time.Date(2026, 3, 18, 0, 0, 0, 0, cst)

func dt(dayOffset, h, m int) time.Time {
	d := base.AddDate(0, 0, dayOffset)
	return time.Date(d.Year(), d.Month(), d.Day(), h, m, 0, 0, cst)
}

type Event struct {
	ID       string
	Title    string
	Start    time.Time
	End      time.Time
	Repeat   string
