// =====================================================================
// 时间窗：三个视图各自的时间窗
// =====================================================================

type Window struct {
	From time.Time
	To   time.Time // 右开区间
}

func DayWindow(anchor time.Time) Window {
	d := time.Date(anchor.Year(), anchor.Month(), anchor.Day(), 0, 0, 0, 0, cst)
	return Window{d, d.AddDate(0, 0, 1)}
}

func WeekWindow(anchor time.Time) Window {
	// ISO 周：周一为一周之始
	d := time.Date(anchor.Year(), anchor.Month(), anchor.Day(), 0, 0, 0, 0, cst)
	offset := (int(d.Weekday()) + 6) % 7 // 周一=0 … 周日=6
	start := d.AddDate(0, 0, -offset)
	return Window{start, start.AddDate(0, 0, 7)}
}

func MonthWindow(anchor time.Time) Window {
	start := time.Date(anchor.Year(), anchor.Month(), 1, 0, 0, 0, 0, cst)
	return Window{start, start.AddDate(0, 1, 0)}
}

func (w Window) contains(t time.Time) bool {
	return !t.Before(w.From) && t.Before(w.To)
}

// =====================================================================
// 可见性过滤
// =====================================================================

func visibleTo(e Event, memberID string) bool {
	switch e.Vis {
	case VisFamily:
		return true
	case VisMembers:
		for _, m := range e.Members {
			if m == memberID {
				return true
			}
		}
		return false
	case VisPrivate:
		return len(e.Members) > 0 && e.Members[0] == memberID
	}
	return false
}

// =====================================================================
// 核心：一次查询，三个视图
// =====================================================================

type ViewResult struct {
	View    string
	Window  Window
	Items   []Event
	Meta    []string
	DaysNum int // 网格天数
}

func Query(anchor time.Time, view string, memberID string) ViewResult {
	var w Window
	var days int
	switch view {
	case "day":
		w, days = DayWindow(anchor), 1
	case "week":
		w, days = WeekWindow(anchor), 7
	case "month":
		w, days = MonthWindow(anchor), daysIn(anchor)
	default:
		return ViewResult{View: view, Meta: []string{"非法 view 值"}}
	}

	var items []Event
	for _, e := range events {
		if !visibleTo(e, memberID) {
			continue
		}
		// ⚠ 关键判定：**跨越时间窗的事件也算命中**
		//    五一出行 04-01 07:00 → 04-04 20:00，在月视图里要出现，
		//    在 04-02 的日视图里也要出现
		if w.contains(e.Start) || w.contains(e.End) ||
			(e.Start.Before(w.From) && e.End.After(w.From)) {
			items = append(items, e)
		}
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Start.Before(items[j].Start) })

	return ViewResult{View: view, Window: w, Items: items, DaysNum: days}
}

func daysIn(t time.Time) int {
	return time.Date(t.Year(), t.Month()+1, 0, 0, 0, 0, 0, cst).Day()
}

