// =====================================================================
// W30 d14：view 参数的实现 —— 日/周/月视图的边界计算。
//
// d13 讲了「三视图是一份数据的三次切片」。今天把边界真算出来。
//
// 这一段的价值全在**边界**：日历系统一半的 bug 出在边界上。
//   · 上周一是几号？跨月时月视图的第一列是上个月还是本月？
//   · 3 月 31 日 + 1 天 = 4 月 1 日（AddDate 的坑）
//   · 周日算不算本周？（ISO 周以周一为首）
//   · 闰年 2 月 29 日在哪个视图里
//
// 本程序跑出 12 个真实日期，逐条对照正确答案。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)

func d(y, m, day int) time.Time {
	return time.Date(y, time.Month(m), day, 0, 0, 0, 0, cst)
}

func dtm(t time.Time, h, m int) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), h, m, 0, 0, cst)
}

type Window struct {
	From time.Time
	To   time.Time
}

// DayWindow：当天 00:00 → 次日 00:00
func DayWindow(a time.Time) Window {
	start := time.Date(a.Year(), a.Month(), a.Day(), 0, 0, 0, 0, cst)
	return Window{start, start.AddDate(0, 0, 1)}
}

// WeekWindow：ISO 周，周一为首
func WeekWindow(a time.Time) Window {
	start := time.Date(a.Year(), a.Month(), a.Day(), 0, 0, 0, 0, cst)
	back := (int(start.Weekday()) + 6) % 7 // 周一=0 … 周日=6
	monday := start.AddDate(0, 0, -back)
	return Window{monday, monday.AddDate(0, 0, 7)}
}

// MonthWindow：本月 1 日 → 下月 1 日
func MonthWindow(a time.Time) Window {
	start := time.Date(a.Year(), a.Month(), 1, 0, 0, 0, 0, cst)
	return Window{start, start.AddDate(0, 1, 0)}
}

// MonthGrid：月视图网格要 6 行 × 7 列，从「包含 1 日的那周周一」开始
func MonthGrid(a time.Time) (Window, int) {
	first := time.Date(a.Year(), a.Month(), 1, 0, 0, 0, 0, cst)
	back := (int(first.Weekday()) + 6) % 7
	gridStart := first.AddDate(0, 0, -back)
	daysIn := time.Date(a.Year(), a.Month()+1, 0, 0, 0, 0, 0, cst).Day()
	rows := (back + daysIn + 6) / 7
	return Window{gridStart, gridStart.AddDate(0, 0, rows*7)}, rows
}

func (w Window) str() string {
	return w.From.Format("2006-01-02") + " → " + w.To.Format("2006-01-02")
}

func (w Window) days() int {
	return int(w.To.Sub(w.From).Hours() / 24)
}

