func strFlag(got, want string) string {
	if got == want {
		return got
	}
	return got + "  ←应为 " + want
}

func parseAnchor(s string) (int, int, int) {
	// "2026-03-01 周日" → 2026, 3, 1
	parts := strings.Fields(s)
	dp := strings.Split(parts[0], "-")
	y := 0
	m := 0
	dd := 0
	fmt.Sscanf(dp[0], "%d", &y)
	fmt.Sscanf(dp[1], "%d", &m)
	fmt.Sscanf(dp[2], "%d", &dd)
	return y, m, dd
}

// =====================================================================
// W30 d15：events 详情接口 —— source_system / source_id 供「前往源对象」深链。
//
// PRD 3.9.6：GET /api/calendar/events/{id} 详情带 source_system/source_id 供深链。
//
// 主线问题：用户在日历上点一条「房贷月供」，怎么跳到 finance 里的那张账单？
//
// 答案不能是「服务端去 finance 查一遍再把详情返回」。
//   那会违反 tech-plan §7.1「一次请求内同步 fan-out 超过 1 个他服务」的禁令，
//   也会让日历接口的延迟依赖 finance 的健康度。
//
// 正确做法：详情接口只返回**地址**，跳转由客户端发起一个新的请求。
// 本程序把这条链路真跑一遍，并演示三种错误做法各自错在哪。
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 3, 18, 9, 0, 0, 0, cst)

func at(dayOffset, h, m int) time.Time {
	d := base.AddDate(0, 0, dayOffset)
	return time.Date(d.Year(), d.Month(), d.Day(), h, m, 0, 0, cst)
}

