type DeepLink struct {
	Available bool   `json:"available"`
	Reason    string `json:"reason,omitempty"`
	Target    string `json:"target,omitempty"`
	Method    string `json:"method,omitempty"`
	// 深链的下一跳：由客户端发起，服务端不代劳
	NextRequest string `json:"next_request,omitempty"`
}

type EventDetail struct {
	ID      string   `json:"id"`
	Title   string   `json:"title"`
	StartAt string   `json:"start_at"`
	EndAt   string   `json:"end_at"`
	Kind    string   `json:"kind"`
	Repeat  string   `json:"repeat,omitempty"`
	Vis     string   `json:"visibility"`
	Members []string `json:"members"`
	Source  struct {
		System string `json:"system"`
		ID     string `json:"id,omitempty"`
	} `json:"source"`
	DoneReturnsTo string   `json:"done_returns_to,omitempty"`
	DeepLink      DeepLink `json:"deep_link"`
}

func GetDetail(id, familyID, memberID string) (int, string, string) {
	for _, e := range events {
		if e.ID != id {
			continue
		}
		// 越权一律 404（S3 d19）
		if e.FamilyID != familyID {
			return 404, "", "跨家庭访问 → 404"
		}
		if !visibleTo(e, memberID) {
			return 404, "", "不属于该成员的可见范围 → 404"
		}

		var d EventDetail
		d.ID = e.ID
		d.Title = e.Title
		d.StartAt = e.Start.Format(time.RFC3339)
		d.EndAt = e.End.Format(time.RFC3339)
		d.Kind = e.Kind
		d.Repeat = e.Repeat
		d.Vis = e.Vis
		d.Members = e.Members
		d.Source.System = e.Source
		d.Source.ID = e.SourceID
		d.DoneReturnsTo = e.DoneReturns

		// 深链构造：三种情形
		switch {
		case e.SourceID == "":
			d.DeepLink = DeepLink{
				Available: false,
				Reason:    "calendar 自持，无源对象",
				Target:    "/pages/calendar/event?id=" + e.ID,
			}
		case e.Source == "finance":
			d.DeepLink = DeepLink{
				Available: true,
				Target:    "/pages/finance/bill?id=" + e.SourceID,
				Method:    "GET",
				NextRequest: "GET /api/finance/bills/{id}   " +
					"（客户端发起，服务端不代劳；超时 ≤300ms、重试 ≤1 次）",
			}
		default:
			d.DeepLink = DeepLink{
				Available: true,
				Target:    "/pages/" + e.Source + "/" + e.Kind + "?id=" + e.SourceID,
				Method:    "GET",
			}
		}

		b, _ := json.MarshalIndent(d, "  ", "  ")
		return 200, string(b), "命中"
	}
	return 404, "", "id 不存在 → 404"
}

func visibleTo(e Event, memberID string) bool {
	switch e.Vis {
	case "family":
		return true
	case "members":
		for _, m := range e.Members {
			if m == memberID {
				return true
			}
		}
		return false
	case "private":
		return len(e.Members) > 0 && e.Members[0] == memberID
	}
	return false
}

