func pt(t time.Time) *time.Time { return &t }

func (s *Store) find(id string) *Todo {
	for _, t := range s.todos {
		if t.ID == id && t.DeletedAt == nil {
			return t
		}
	}
	return nil
}

// =====================================================================
// 请求 / 响应
// =====================================================================

type CreateTodoReq struct {
	Title           string     `json:"title"`
	MemberID        string     `json:"member_id"`
	DueAt           *time.Time `json:"due_at"`
	ClientRequestID string     `json:"client_request_id"`
}

type UpdateTodoReq struct {
	Status          string     `json:"status,omitempty"`
	Title           string     `json:"title,omitempty"`
	MemberID        string     `json:"member_id,omitempty"`
	DueAt           *time.Time `json:"due_at,omitempty"`
	Version         int        `json:"version"`
	ClientRequestID string     `json:"client_request_id"`
}

type Envelope struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data,omitempty"`
}

// =====================================================================
// Handler
// =====================================================================

type Server struct {
	store *Store
	// 记录本轮发出的事件，供打印
	fired []string
}

func (s *Server) CreateTodo(w http.ResponseWriter, r *http.Request) {
	var req CreateTodoReq
	body, _ := io.ReadAll(r.Body)
	_ = json.Unmarshal(body, &req)
	member := memberFrom(r)

	// ① 铁律三：写接口必带 client_request_id
	if req.ClientRequestID == "" {
		writeJSON(w, 400, Envelope{40001, "client_request_id 必填", nil})
		return
	}
	// ② 幂等：同一个 client_request_id 返回同一个结果
	idemKey := member.Family + ":" + req.ClientRequestID
	if id, ok := s.store.idem[idemKey]; ok {
		t := s.store.find(id)
		writeJSON(w, 200, Envelope{0, "ok（幂等命中，返回首次创建的同一对象）",
			map[string]any{"todo": t, "idempotent_replay": true}})
		return
	}
	// ③ 校验
	if strings.TrimSpace(req.Title) == "" {
		writeJSON(w, 400, Envelope{40002, "title 不能为空", nil})
		return
	}
	if req.MemberID == "" {
		writeJSON(w, 400, Envelope{40003, "member_id 必填", nil})
		return
	}
	if req.DueAt != nil && req.DueAt.Before(base) {
		writeJSON(w, 400, Envelope{40004, "due_at 不能早于当前时间", nil})
		return
	}
	// ④ 写入
	s.store.seq++
	t := &Todo{
		ID: fmt.Sprintf("todo_new_%02d", s.store.seq), FamilyID: member.Family,
		MemberID: req.MemberID, CreatorID: member.Member,
		Title: req.Title, DueAt: req.DueAt, Status: "open",
		SourceSystem: "calendar", Kind: "todo", Version: 1,
		CreatedAt: base, UpdatedAt: base,
	}
	s.store.todos = append(s.store.todos, t)
	s.store.idem[idemKey] = t.ID

	writeJSON(w, 201, Envelope{0, "ok", map[string]any{"todo": t}})
}

func (s *Server) ListTodos(w http.ResponseWriter, r *http.Request) {
	member := memberFrom(r)
	scope := r.URL.Query().Get("scope")
	if scope == "" {
		scope = "assigned"
	}
	if scope != "assigned" && scope != "created" && scope != "archived" {
		writeJSON(w, 400, Envelope{40005, "scope 必须是 assigned|created|archived", nil})
		return
	}

	var hit []*Todo
	for _, t := range s.store.todos {
		if t.FamilyID != member.Family || t.DeletedAt != nil {
			continue
		}
		switch scope {
		case "assigned":
			if t.MemberID == member.Member && t.Status == "open" {
				hit = append(hit, t)
			}
		case "created":
			if t.CreatorID == member.Member && t.Status == "open" {
				hit = append(hit, t)
			}
		case "archived":
			if t.Status == "archived" {
				hit = append(hit, t)
			}
		}
	}
	// 排序：due_at NULLS LAST，然后 id
	sort.Slice(hit, func(i, j int) bool {
		a, b := hit[i].DueAt, hit[j].DueAt
		if a == nil {
			return false
		}
		if b == nil {
			return true
		}
		if a.Equal(*b) {
			return hit[i].ID < hit[j].ID
		}
		return a.Before(*b)
	})

	idx := map[string]string{
		"assigned": "idx_calendar_todo_family_member_due",
		"created":  "idx_calendar_todo_family_creator_due",
		"archived": "idx_calendar_todo_family_archived",
	}[scope]

	items := make([]*Todo, len(hit))
	copy(items, hit)
	writeJSON(w, 200, Envelope{0, "ok", map[string]any{
		"scope": scope, "items": items,
		"next_cursor": nil, "index_used": idx,
	}})
}

func (s *Server) UpdateTodo(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/calendar/todos/")
	member := memberFrom(r)

	var req UpdateTodoReq
	body, _ := io.ReadAll(r.Body)
	_ = json.Unmarshal(body, &req)

	t := s.store.find(id)
	// 越权一律 404
	if t == nil || t.FamilyID != member.Family {
		writeJSON(w, 404, Envelope{40400, "待办不存在", nil})
		return
	}
	// version 必填
	if req.Version == 0 {
		writeJSON(w, 400, Envelope{40006, "version 必填", nil})
		return
	}
	// 乐观锁冲突 → 409，且**不改动数据**
	if req.Version != t.Version {
		writeJSON(w, 409, Envelope{
			40900,
			"版本冲突，请刷新后重试",
			map[string]any{"current_version": t.Version, "your_version": req.Version},
		})
		return
	}
	// 状态机：只允许 open → done / cancelled / archived
	if req.Status != "" && req.Status != t.Status {
		if t.Status != "open" {
			writeJSON(w, 409, Envelope{40901, "当前状态不可再变更：" + t.Status, nil})
			return
		}
		switch req.Status {
		case "done", "cancelled", "archived":
		default:
			writeJSON(w, 400, Envelope{40007, "非法目标状态：" + req.Status, nil})
			return
		}
	}

	// 应用变更
	if req.Title != "" {
		t.Title = req.Title
	}
	if req.MemberID != "" {
		t.MemberID = req.MemberID
	}
	if req.DueAt != nil {
		t.DueAt = req.DueAt
	}
	prevStatus := t.Status
	if req.Status != "" {
		t.Status = req.Status
	}
	if t.Status == "done" && t.DoneAt == nil {
		da := base
		t.DoneAt = &da
	}
	if t.Status != "done" {
		t.DoneAt = nil
	}
	t.Version++
	t.UpdatedAt = base

	data := map[string]any{"todo": t, "version": t.Version}

	// 完成 → 回写业务对象 + 发事件
	if prevStatus == "open" && t.Status == "done" {
		wb := s.writeback(t)
		ev := "calendar.todo.completed"
		key := ev + ":" + t.ID
		if !s.store.firedOnce[key] {
			s.store.firedOnce[key] = true
			s.fired = append(s.fired, key)
			data["event_published"] = ev
		}
		data["writeback"] = wb
	}
	writeJSON(w, 200, Envelope{0, "ok", data})
}

func (s *Server) writeback(t *Todo) string {
	if t.DoneReturnsTo == "" {
		return "跳过回写（calendar 自持，无源对象）"
	}
	parts := strings.Split(t.DoneReturnsTo, ":")
	if len(parts) != 4 {
		return "回写失败：done_returns_to 格式错误（4 段）"
	}
	b, ok := s.store.bills[parts[1]]
	if !ok {
		return "找不到来源对象 " + parts[1] + " —— 孤儿引用"
	}
	if parts[2] == "status" {
		old := b.Status
		b.Status = parts[3]
		return parts[1] + ".status: " + old + " → " + b.Status
	}
	return "未知字段 " + parts[2]
}

// ---- 身份（真实项目里来自 token 中间件，这里用请求头模拟）----

type Member struct {
	Family string
	Member string
	Role   string
}

func memberFrom(r *http.Request) Member {
	return Member{
		Family: r.Header.Get("X-Family"),
		Member: r.Header.Get("X-Member"),
		Role:   r.Header.Get("X-Role"),
	}
}

func writeJSON(w http.ResponseWriter, code int, body Envelope) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(body)
}

