	mux.HandleFunc("/api/calendar/todos", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPost {
			srv.CreateTodo(w, r)
			return
		}
		srv.ListTodos(w, r)
	})
	mux.HandleFunc("/api/calendar/todos/", srv.UpdateTodo)

