	go func() { _ = hs.Serve(ln) }()
	defer func() { _ = hs.Close() }()

	do := func(method, path, body string, hdr map[string]string) (int, string) {
		req, _ := http.NewRequest(method, "http://127.0.0.1:18101"+path, strings.NewReader(body))
		for k, v := range hdr {
			req.Header.Set(k, v)
		}
		resp, err := (&http.Client{Timeout: 3 * time.Second}).Do(req)
		if err != nil {
			return 0, "ERR " + firstSeg(err.Error())
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		return resp.StatusCode, strings.TrimRight(string(b), "\n")
	}

	mom := map[string]string{"X-Family": "fam_zhang", "X-Member": "mem_mom", "X-Role": "owner"}
	dad := map[string]string{"X-Family": "fam_zhang", "X-Member": "mem_dad", "X-Role": "member"}

