		{"GET", "/api/calendar/todos", "ListTodos", "scope 三值枚举；游标分页"},
		{"PUT", "/api/calendar/todos/{id}", "UpdateTodo", "**必带 version**；状态机校验"},
	}
	for i, r := range routes {
