		fmt.Printf("     handler  %s\n", r.Handler)
		fmt.Printf("     守卫    %s\n", r.Guard)
	}
	fmt.Println()

	// ---------------- 2. POST ----------------
	fmt.Println("=== 2. POST /api/calendar/todos ===")
	fmt.Println()
	fmt.Println("  ① 缺 client_request_id（铁律三）")
	code, body := do("POST", "/api/calendar/todos",
		`{"title":"买牛奶","member_id":"mem_mom"}`, mom)
	fmt.Printf("    → %d  %s\n", code, body)
