	fmt.Println("  ② 标题为空")
	code, body = do("POST", "/api/calendar/todos",
		`{"title":"   ","member_id":"mem_mom","client_request_id":"cr_001"}`, mom)
	fmt.Printf("    → %d  %s\n", code, body)
	fmt.Println()

	fmt.Println("  ③ due_at 在过去")
	code, body = do("POST", "/api/calendar/todos",
		`{"title":"买牛奶","member_id":"mem_mom","due_at":"2026-03-01T09:00:00+08:00","client_request_id":"cr_002"}`, mom)
	fmt.Printf("    → %d  %s\n", code, body)
	fmt.Println()

	fmt.Println("  ④ 正常创建")
	code, body = do("POST", "/api/calendar/todos",
		`{"title":"买牛奶","member_id":"mem_mom","due_at":"2026-03-19T18:00:00+08:00","client_request_id":"cr_003"}`, mom)
