func firstSeg(e string) string {
	if i := strings.Index(e, ": "); i > 0 {
		return e[:i]
	}
	return e
}

func prettyTodo(body string) string {
	var env Envelope
	if err := json.Unmarshal([]byte(body), &env); err != nil {
		return body
	}
	d, ok := env.Data.(map[string]any)
	if !ok {
		return body
	}
	replay := ""
	if v, ok := d["idempotent_replay"].(bool); ok && v {
		replay = "  [幂等重放]"
	}
	t, _ := d["todo"].(map[string]any)
	if t == nil {
		return body
	}
	due := "（无）"
	if dv, ok := t["due_at"].(string); ok && dv != "" {
		tt, _ := time.Parse(time.RFC3339, dv)
		due = tt.In(cst).Format("2006-01-02 15:04")
	}
	return fmt.Sprintf("id=%v title=%q status=%v version=%v creator=%v member=%v due=%v%s",
		t["id"], t["title"], t["status"], t["version"], t["creator_id"], t["member_id"], due, replay)
}

func prettyUpdate(body string) string {
	var env Envelope
	if err := json.Unmarshal([]byte(body), &env); err != nil {
		return body
	}
	d, ok := env.Data.(map[string]any)
	if !ok {
		return body
	}
	t, _ := d["todo"].(map[string]any)
	if t == nil {
		return body
	}
	out := fmt.Sprintf("status=%v version=%v", t["status"], t["version"])
	if wb, ok := d["writeback"].(string); ok {
		out += "  writeback=" + wb
	}
	if ev, ok := d["event_published"].(string); ok {
		out += "  event=" + ev
	}
	return out
}

// =====================================================================
// W30 d17：Reminder 的 3 条接口 —— 创建、列表、编辑。
//
// PRD 3.9.6：编辑（时间、周期、**提前量**、渠道、暂停）；
//           暂停与删除发 {code}.due.revoked。
//
// 与 Todo 的三个差别：
//   ① Reminder 有 **advance_minutes（提前量）** —— 提醒不是到点才触发，
//      而是「到期时刻 - 提前量」。这是它多出来的第一个参数。
//   ② Reminder 有 **channel（渠道）** —— 站内 / push / 短信
//   ③ Reminder 有 **status=paused** —— 可暂停而不删，
//      暂停发 due.revoked，来源面要把注册项置为失效
//
// 本程序真起服务，把 3 条接口 + 到期触发真跑一遍。
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 3, 18, 9, 0, 0, 0, cst)

func at(dayOffset, h, m int) time.Time {
	d := base.AddDate(0, 0, dayOffset)
	return time.Date(d.Year(), d.Month(), d.Day(), h, m, 0, 0, cst)
}

func pt(t time.Time) *time.Time { return &t }

// =====================================================================
// 模型
// =====================================================================

type Reminder struct {
	ID         string     `json:"id"`
	FamilyID   string     `json:"family_id"`
	OwnerID    string     `json:"owner_id"`
	Title      string     `json:"title"`
	Type       string     `json:"type"`        // time / location / due
	TriggerAt  time.Time  `json:"trigger_at"`  // 业务触发时刻（到期时刻）
	AdvanceMin int        `json:"advance_min"` // 提前量（分钟）
	FireAt     time.Time  `json:"fire_at"`     // 实际提醒时刻 = TriggerAt - AdvanceMin
	Repeat     string     `json:"repeat,omitempty"`
	Status     string     `json:"status"`  // active / paused / fired
	Channel    string     `json:"channel"` // inapp / push / sms
	EventID    string     `json:"calendar_event_id,omitempty"`
	SourceSys  string     `json:"source_system"`
	SourceID   string     `json:"source_id,omitempty"`
	Kind       string     `json:"kind"`
	NextAt     *time.Time `json:"next_at"`
	Version    int        `json:"version"`
	DeletedAt  *time.Time `json:"deleted_at,omitempty"`
	CreatedAt  time.Time  `json:"created_at"`
	UpdatedAt  time.Time  `json:"updated_at"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

type CreateReminderReq struct {
	Title           string     `json:"title"`
	OwnerID         string     `json:"owner_id"`
	Type            string     `json:"type"`
	TriggerAt       *time.Time `json:"trigger_at"`
	AdvanceMin      int        `json:"advance_min"`
	Repeat          string     `json:"repeat"`
	Channel         string     `json:"channel"`
	CalendarEventID string     `json:"calendar_event_id"`
	ClientRequestID string     `json:"client_request_id"`
}

type UpdateReminderReq struct {
	TriggerAt       *time.Time `json:"trigger_at"`
	AdvanceMin      *int       `json:"advance_min"`
	Repeat          *string    `json:"repeat"`
	Channel         *string    `json:"channel"`
	Status          *string    `json:"status"`
	ClientRequestID string     `json:"client_request_id"`
	Version         int        `json:"version"`
}

type Envelope struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data,omitempty"`
}

// =====================================================================
// 合法取值
// =====================================================================

var validChannels = map[string]bool{"inapp": true, "push": true, "sms": true}
var validTypes = map[string]bool{"time": true, "location": true, "due": true}
var validRepeats = map[string]bool{
	"": true, "once": true, "daily": true,
	"weekly:MO": true, "weekly:TU": true, "weekly:WE": true,
	"weekly:TH": true, "weekly:FR": true, "weekly:SA": true, "weekly:SU": true,
	"weekly:MO,WE,FR": true, "monthly:20": true, "yearly:03-20": true,
}

var maxAdvanceMin = 7 * 24 * 60 // 最多提前 7 天

// =====================================================================
// Server
// =====================================================================

type Server struct {
	reminders []*Reminder
	idem      map[string]string
	seq       int
	fired     []string
	revoked   []string
}

