}

func (s *Server) CreateReminder(w http.ResponseWriter, r *http.Request) {
	var req CreateReminderReq
	body, _ := io.ReadAll(r.Body)
	_ = json.Unmarshal(body, &req)
	m := memberFrom(r)

	if req.ClientRequestID == "" {
		writeJSON(w, 400, Envelope{40001, "client_request_id 必填", nil})
		return
	}
	ik := m.Family + ":" + req.ClientRequestID
	if id, ok := s.idem[ik]; ok {
		writeJSON(w, 200, Envelope{0, "ok（幂等命中）", map[string]any{
			"reminder": s.find(id), "idempotent_replay": true}})
		return
	}
	if strings.TrimSpace(req.Title) == "" {
		writeJSON(w, 400, Envelope{40002, "title 不能为空", nil})
		return
	}
	if req.OwnerID == "" {
		writeJSON(w, 400, Envelope{40003, "owner_id 必填", nil})
		return
	}
	t := req.Type
	if t == "" {
		t = "time"
	}
	if !validTypes[t] {
		writeJSON(w, 400, Envelope{40008, "type 必须是 time|location|due", nil})
		return
	}
	if req.TriggerAt == nil {
		writeJSON(w, 400, Envelope{40009, "trigger_at 必填", nil})
		return
	}
	if req.TriggerAt.Before(base) {
		writeJSON(w, 400, Envelope{40010, "trigger_at 不能早于当前时间", nil})
		return
	}
	// ★ 提前量校验：这是 Reminder 独有的
	if req.AdvanceMin < 0 {
		writeJSON(w, 400, Envelope{40011, "advance_min 不能为负", nil})
		return
	}
	if req.AdvanceMin > maxAdvanceMin {
		writeJSON(w, 400, Envelope{40012,
			fmt.Sprintf("advance_min 最多 %d 分钟（7 天），收到 %d", maxAdvanceMin, req.AdvanceMin), nil})
		return
	}
	// 提前量不能吃掉触发时刻本身
	if req.AdvanceMin > int(req.TriggerAt.Sub(base).Minutes()) {
		writeJSON(w, 400, Envelope{40013, "提前量大于「距现在的时间」，提醒会在创建时就已过期", nil})
		return
	}
	ch := req.Channel
	if ch == "" {
		ch = "inapp"
	}
	if !validChannels[ch] {
		writeJSON(w, 400, Envelope{40014, "channel 必须是 inapp|push|sms", nil})
		return
	}
	if !validRepeats[req.Repeat] {
		writeJSON(w, 400, Envelope{40015, "repeat 取值不合法：" + req.Repeat, nil})
		return
	}

	s.seq++
	fire := req.TriggerAt.Add(-time.Duration(req.AdvanceMin) * time.Minute)
	rem := &Reminder{
		ID: fmt.Sprintf("rem_new_%02d", s.seq), FamilyID: m.Family, OwnerID: req.OwnerID,
		Title: req.Title, Type: t, TriggerAt: *req.TriggerAt, AdvanceMin: req.AdvanceMin,
		FireAt: fire, Repeat: req.Repeat, Status: "active", Channel: ch,
		EventID: req.CalendarEventID, SourceSys: "calendar", Kind: "reminder",
		NextAt: &fire, Version: 1, CreatedAt: base, UpdatedAt: base,
	}
	s.reminders = append(s.reminders, rem)
	s.idem[ik] = rem.ID
	writeJSON(w, 201, Envelope{0, "ok", map[string]any{"reminder": rem}})
}

func (s *Server) ListReminders(w http.ResponseWriter, r *http.Request) {
	m := memberFrom(r)
	scope := r.URL.Query().Get("scope")
	if scope == "" {
		scope = "mine"
	}
	if scope != "mine" && scope != "family" && scope != "paused" {
		writeJSON(w, 400, Envelope{40016, "scope 必须是 mine|family|paused", nil})
		return
	}
	var hit []*Reminder
	for _, rem := range s.reminders {
		if rem.FamilyID != m.Family || rem.DeletedAt != nil {
			continue
		}
		switch scope {
		case "mine":
			if rem.OwnerID == m.Member {
				hit = append(hit, rem)
			}
		case "family":
			hit = append(hit, rem)
		case "paused":
			if rem.Status == "paused" {
				hit = append(hit, rem)
			}
		}
	}
	sort.Slice(hit, func(i, j int) bool {
		a, b := hit[i].NextAt, hit[j].NextAt
		if a == nil {
			return false
		}
		if b == nil {
			return true
		}
		return a.Before(*b)
	})
	items := append([]*Reminder{}, hit...)
	writeJSON(w, 200, Envelope{0, "ok", map[string]any{
		"scope": scope, "items": items, "next_cursor": nil,
		"index_used": "idx_calendar_reminder_family_owner_next",
	}})
}

func (s *Server) UpdateReminder(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/calendar/reminders/")
	m := memberFrom(r)
	var req UpdateReminderReq
	body, _ := io.ReadAll(r.Body)
	_ = json.Unmarshal(body, &req)

	rem := s.find(id)
	if rem == nil || rem.FamilyID != m.Family {
		writeJSON(w, 404, Envelope{40400, "提醒不存在", nil})
		return
	}
	if req.Version == 0 {
		writeJSON(w, 400, Envelope{40006, "version 必填", nil})
		return
	}
	if req.Version != rem.Version {
		writeJSON(w, 409, Envelope{40900, "版本冲突，请刷新后重试",
			map[string]any{"current_version": rem.Version, "your_version": req.Version}})
		return
	}

	prevStatus := rem.Status
	changes := []string{}

	if req.TriggerAt != nil {
		if req.TriggerAt.Before(base) {
			writeJSON(w, 400, Envelope{40010, "trigger_at 不能早于当前时间", nil})
			return
		}
		rem.TriggerAt = *req.TriggerAt
		changes = append(changes, "trigger_at")
	}
	if req.AdvanceMin != nil {
		if *req.AdvanceMin < 0 || *req.AdvanceMin > maxAdvanceMin {
			writeJSON(w, 400, Envelope{40012, "advance_min 越界", nil})
			return
		}
		rem.AdvanceMin = *req.AdvanceMin
		changes = append(changes, "advance_min")
	}
	if req.Repeat != nil {
		if !validRepeats[*req.Repeat] {
			writeJSON(w, 400, Envelope{40015, "repeat 取值不合法：" + *req.Repeat, nil})
			return
		}
		rem.Repeat = *req.Repeat
		changes = append(changes, "repeat")
	}
	if req.Channel != nil {
		if !validChannels[*req.Channel] {
			writeJSON(w, 400, Envelope{40014, "channel 必须是 inapp|push|sms", nil})
			return
		}
		rem.Channel = *req.Channel
		changes = append(changes, "channel")
	}
	if req.Status != nil {
		switch *req.Status {
		case "active", "paused":
			rem.Status = *req.Status
			changes = append(changes, "status")
		default:
			writeJSON(w, 400, Envelope{40007, "status 只能是 active|paused（fired 由系统写）", nil})
			return
		}
	}

	// 重算 fire_at = trigger_at - advance_min
	rem.FireAt = rem.TriggerAt.Add(-time.Duration(rem.AdvanceMin) * time.Minute)
	if rem.Status == "active" {
		rem.NextAt = pt(rem.FireAt)
		rem.RevokedAt = nil
	} else {
		rem.NextAt = nil
		if rem.Status == "paused" && rem.RevokedAt == nil {
			rem.RevokedAt = pt(base)
		}
	}
	rem.Version++
	rem.UpdatedAt = base

	data := map[string]any{
		"reminder": rem, "changed": changes, "version": rem.Version,
	}

	// ★ 暂停 → 发 {code}.due.revoked
	if prevStatus != "paused" && rem.Status == "paused" {
		key := rem.SourceSys + ".due.revoked:" + rem.SourceID + ":paused"
		s.revoked = append(s.revoked, key)
		data["event_published"] = rem.SourceSys + ".due.revoked"
		data["revoke_reason"] = "paused"
	}
	// 恢复 → 发 {code}.due.registered（重新登记）
	if prevStatus == "paused" && rem.Status == "active" && rem.SourceID != "" {
		key := rem.SourceSys + ".due.registered:" + rem.SourceID + ":" + rem.TriggerAt.Format(time.RFC3339)
		s.revoked = append(s.revoked, key)
		data["event_published"] = rem.SourceSys + ".due.registered"
		data["revoke_reason"] = "resumed"
	}
	writeJSON(w, 200, Envelope{0, "ok", data})
}

// ---- 到期触发扫描（后台任务，不是接口）----

func (s *Server) DueScan(now time.Time, familyID string) []*Reminder {
	var hit []*Reminder
	for _, r := range s.reminders {
		if r.FamilyID != familyID || r.Status != "active" || r.DeletedAt != nil {
			continue
		}
		if r.NextAt == nil {
			continue
		}
		if !r.NextAt.After(now) {
			hit = append(hit, r)
		}
	}
	sort.Slice(hit, func(i, j int) bool { return hit[i].NextAt.Before(*hit[j].NextAt) })
	return hit
}

type Member struct{ Family, Member, Role string }

func memberFrom(r *http.Request) Member {
	return Member{r.Header.Get("X-Family"), r.Header.Get("X-Member"), r.Header.Get("X-Role")}
}

func writeJSON(w http.ResponseWriter, code int, body Envelope) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(body)
}

