func advStr(m int) string {
	switch {
	case m == 0:
		return "0"
	case m%1440 == 0:
		return fmt.Sprintf("%d天", m/1440)
	case m%60 == 0:
		return fmt.Sprintf("%d小时", m/60)
	default:
		return fmt.Sprintf("%d分", m)
	}
}

func prettyRem(body string) string {
	var env Envelope
	if err := json.Unmarshal([]byte(body), &env); err != nil {
		return body
	}
	d, ok := env.Data.(map[string]any)
	if !ok {
		return env.Message
	}
	r, _ := d["reminder"].(map[string]any)
	if r == nil {
		return env.Message
	}
	replay := ""
	if v, ok := d["idempotent_replay"].(bool); ok && v {
		replay = "  [幂等重放]"
	}
	fire, _ := r["fire_at"].(string)
	ft, _ := time.Parse(time.RFC3339, fire)
	return fmt.Sprintf("id=%v title=%q status=%v advance=%vmin fire_at=%s channel=%v%s",
		r["id"], r["title"], r["status"], r["advance_min"],
		ft.In(cst).Format("2006-01-02 15:04"), r["channel"], replay)
}

func prettyUpdate(body string) string {
	var env Envelope
	if err := json.Unmarshal([]byte(body), &env); err != nil {
		return body
	}
	if env.Data == nil {
		return env.Message
	}
	d, ok := env.Data.(map[string]any)
	if !ok {
		return env.Message
	}
	r, _ := d["reminder"].(map[string]any)
	ch, _ := d["changed"].([]any)
	names := []string{}
	for _, c := range ch {
		names = append(names, fmt.Sprint(c))
	}
	ver := d["version"]
	na := "—"
	if r != nil {
		if nv, ok := r["next_at"].(string); ok && nv != "" {
			t, _ := time.Parse(time.RFC3339, nv)
			na = t.In(cst).Format("01-02 15:04")
		}
	}
	ev := ""
	if e, ok := d["event_published"].(string); ok {
		ev = "  event=" + e
	}
	return fmt.Sprintf("version=%v changed=[%s] next_at=%s%s", ver, strings.Join(names, ","), na, ev)
}

