type Issue struct {
	Kind string // "未登记" / "未实现" / "守卫缺失" / "幂等缺失"
	Item string
	Why  string
}

// Check 比较两份清单，返回所有偏差
func Check(reg []Registered, imp []Implemented) []Issue {
	var issues []Issue
	regSet := map[string]bool{}
	for _, r := range reg {
		regSet[r.Method+" "+r.Path] = true
	}
	impSet := map[string]bool{}
	for _, i := range imp {
		key := i.Method + " " + i.Path
		impSet[key] = true
		if !regSet[key] {
			issues = append(issues, Issue{"未登记", key,
				"PRD 22.2 第 7 条：实现文档用到但未登记的接口一律视为缺陷"})
		}
	}
	for _, r := range reg {
		key := r.Method + " " + r.Path
		if !impSet[key] {
			issues = append(issues, Issue{"未实现", key,
				"登记面有但代码没实现 —— 契约骗人比缺接口更危险"})
		}
	}
	// 幂等要求
	for _, r := range reg {
		if !r.Idem {
			continue
		}
		key := r.Method + " " + r.Path
		for _, i := range imp {
			if i.Method+" "+i.Path != key {
				continue
			}
			if !strings.Contains(i.Guard, "client_request_id") {
				issues = append(issues, Issue{"幂等缺失", key,
					"登记面要求 client_request_id，实现里没有对应校验"})
			}
		}
	}
	// version 要求
	for _, r := range reg {
		if !r.Ver {
			continue
		}
		key := r.Method + " " + r.Path
		for _, i := range imp {
			if i.Method+" "+i.Path != key {
				continue
			}
			if !strings.Contains(i.Guard, "version") {
				issues = append(issues, Issue{"守卫缺失", key,
					"登记面要求带 version，实现里没有乐观锁校验"})
			}
		}
	}
	sort.Slice(issues, func(i, j int) bool {
		if issues[i].Kind != issues[j].Kind {
			return issues[i].Kind < issues[j].Kind
		}
		return issues[i].Item < issues[j].Item
	})
	return issues
}

