func yesNo(b bool) string {
	if b {
		return "是"
	}
	return "否"
}

// =====================================================================
// W31 d19：周期规则要表达什么 —— 每天/每周/每月/每年、自定义、跳过、顺延。
//
// PRD 3.9.2 的周期任务需求只有一行：
//   「周期任务：每天/周/月/年、自定义、跳过、顺延」
//
// 但这七个词（每天/周/月/年/自定义/跳过/顺延）背后是一整套表达式设计。
// 今天把「表达式要表达什么」拆成六个维度，并把七种表达法跑一遍。
//
// 关键立场：PRD 明令「周期任务与重复规则语义沿用三张表既有的 repeat 字段，
// **不得另立 calendar_recurrence 之类的重复规则表**」。
// 所以 repeat 是一个 VARCHAR(64) 的字符串，它必须自足 —— 不依赖别的表。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 3, 18, 9, 0, 0, 0, cst)

// =====================================================================
// Repeat 是重复规则的结构体（d25 会讲它怎么序列化成字符串）
// =====================================================================

type Freq int

const (
	FreqNone Freq = iota // once
	FreqDaily
	FreqWeekly
	FreqMonthly
	FreqYearly
	FreqCustom
)

func (f Freq) String() string {
	switch f {
	case FreqNone:
		return "once"
	case FreqDaily:
		return "daily"
	case FreqWeekly:
		return "weekly"
	case FreqMonthly:
		return "monthly"
	case FreqYearly:
		return "yearly"
	default:
		return "custom"
	}
}

type Repeat struct {
	Freq      Freq
	Interval  int   // 间隔（每 N 天/周/月/年）
	Weekdays  []int // 1=周一 … 7=周日（ISO）
	MonthDay  int   // 每月第几天；-1 = 当月最后一天
	MonthLast bool  // monthly:last —— 每月最后一天
	YearMonth int   // 1..12
	YearDay   int   // 1..366
	YearLeap  bool  // yearly:02-29 —— 只在闰年触发
	Until     *time.Time
	Count     int // 最多重复几次；0 = 不限
	SkipRule  string
	ShiftRule string
}

// ---- Parse：把字符串解析成 Repeat（d25 会讲存储格式，这里先能解析）----
func Parse(s string) (Repeat, error) {
	if s == "" || s == "once" {
		return Repeat{Freq: FreqNone, Interval: 1}, nil
	}
	if s == "daily" {
		return Repeat{Freq: FreqDaily, Interval: 1}, nil
	}
	if strings.HasPrefix(s, "weekly:") {
		r := Repeat{Freq: FreqWeekly, Interval: 1}
		for _, w := range strings.Split(strings.TrimPrefix(s, "weekly:"), ",") {
			r.Weekdays = append(r.Weekdays, wdFromCode(w))
		}
		sort.Ints(r.Weekdays)
		return r, nil
	}
	if strings.HasPrefix(s, "monthly:") {
		arg := strings.TrimPrefix(s, "monthly:")
		if arg == "last" {
			return Repeat{Freq: FreqMonthly, Interval: 1, MonthLast: true, MonthDay: -1}, nil
		}
		d := 0
		fmt.Sscanf(arg, "%d", &d)
		return Repeat{Freq: FreqMonthly, Interval: 1, MonthDay: d}, nil
	}
	if strings.HasPrefix(s, "yearly:") {
		arg := strings.TrimPrefix(s, "yearly:")
		if arg == "02-29" {
			return Repeat{Freq: FreqYearly, Interval: 1, YearMonth: 2, YearDay: 60, YearLeap: true}, nil
		}
		mp := strings.Split(arg, "-")
		mo, dd := 0, 0
		fmt.Sscanf(mp[0], "%d", &mo)
		fmt.Sscanf(mp[1], "%d", &dd)
		return Repeat{Freq: FreqYearly, Interval: 1, YearMonth: mo, YearDay: dd}, nil
	}
	if strings.HasPrefix(s, "custom:") {
		return Repeat{Freq: FreqCustom, Interval: 1}, nil
	}
	return Repeat{}, fmt.Errorf("无法解析：%s", s)
}

var wdCodes = map[string]int{"MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6, "SU": 7}

func wdFromCode(c string) int {
	if v, ok := wdCodes[c]; ok {
		return v
	}
	return 0
}

// ---- Occurrences：算出接下来 N 个触发日期 ----
// 今天只做「无跳过、无顺延」的基础版；d20-d23 会逐步加上。
func Occurrences(r Repeat, from time.Time, n int) []time.Time {
	var out []time.Time
	switch r.Freq {
	case FreqNone:
		return []time.Time{from}
	case FreqDaily:
		t := from
		for i := 0; i < n; i++ {
			out = append(out, t)
			t = t.AddDate(0, 0, r.Interval)
		}
	case FreqWeekly:
		cur := startOfWeek(from)
		for i := 0; i < n; i++ {
			for _, wd := range r.Weekdays {
				d := cur.AddDate(0, 0, wd-1)
				if d.Before(from) {
					continue
				}
				d = sameTimeOfDay(d, from)
				if !d.Before(from) {
					out = append(out, d)
				}
			}
			cur = cur.AddDate(0, 0, 7*r.Interval)
			if len(out) >= n {
				break
			}
		}
		// 截断到 n
		for len(out) > n {
			out = out[:len(out)-1]
		}
	case FreqMonthly:
		y, m := from.Year(), int(from.Month())
		step := 0 // 已经走了多少个 interval 周期
		for i := 0; i < n*2 && len(out) < n; i++ {
			// 只在 interval 的整倍数上取
			if step%r.Interval == 0 {
				day := r.MonthDay
				if r.MonthLast {
					day = daysInMonth(y, m)
				}
				d := safeDate(y, m, day)
				if !d.Before(from) {
					out = append(out, sameTimeOfDay(d, from))
				}
			}
			step++
			y, m = nextMonth(y, m)
		}
	case FreqYearly:
		y := from.Year()
		for i := 0; i < n; i++ {
			var d time.Time
			if r.YearLeap {
				if !isLeap(y) {
					y++
					continue
				}
				d = safeDate(y, 2, 29)
			} else {
				d = safeDate(y, r.YearMonth, dayOfYear(r.YearMonth, r.YearDay, y))
			}
			if d.Before(from) {
				y++
				continue
			}
			out = append(out, sameTimeOfDay(d, from))
			y++
		}
	default:
		return nil
	}
	return out
}

func startOfWeek(t time.Time) time.Time {
	d := time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, cst)
	back := (int(d.Weekday()) + 6) % 7
	return d.AddDate(0, 0, -back)
}

func sameTimeOfDay(d, ref time.Time) time.Time {
	return time.Date(d.Year(), d.Month(), d.Day(), ref.Hour(), ref.Minute(), 0, 0, cst)
}

func daysInMonth(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, cst).Day()
}

func safeDate(y, m, d int) time.Time {
	max := daysInMonth(y, m)
	if d > max {
		d = max
	}
	if d < 1 {
		d = 1
	}
	return time.Date(y, time.Month(m), d, 0, 0, 0, 0, cst)
}

func nextMonth(y, m int) (int, int) {
	m++
	if m > 12 {
		m = 1
		y++
	}
	return y, m
}

func isLeap(y int) bool {
	return time.Date(y, 3, 0, 0, 0, 0, 0, cst).Day() == 29
}

func dayOfYear(month, doy, y int) int {
	// 把「月 + 第几天」转成日；本程序里 yearly 的第二段直接当「几号」用
	return doy
}

