func seqStr(seq []time.Time, n int) string {
	var parts []string
	for i := 0; i < len(seq) && i < n; i++ {
		t := seq[i]
		if i == 0 {
			parts = append(parts, t.Format("01-02"))
		} else {
			gap := int(t.Sub(seq[i-1]).Hours() / 24)
			parts = append(parts, t.Format("01-02")+fmt.Sprintf("(+%d)", gap))
		}
	}
	return strings.Join(parts, "  ")
}

// =====================================================================
// W31 d20：每周规则 —— 周几、间隔几周、时区（真跑日期序列）。
//
// 每周规则是所有周期规则里最容易写错的一个，原因是它有两个「维度」要交叉：
//   ① 一周里的哪几天（weekdays）
//   ② 隔几周（interval）
//
// 再叠上第三个：时区。跨时区家庭里，「每周一早上 8 点」是按谁的时区？
//
// 本程序跑出：
//   · 六种 weekdays 组合的真实序列
//   · 三种 interval 的真实序列
//   · 跨时区时「每周一 8 点」在两个时区分别是什么时刻
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 3, 18, 8, 0, 0, 0, cst) // 周三 08:00

var wdCodes = map[int]string{1: "MO", 2: "TU", 3: "WE", 4: "TH", 5: "FR", 6: "SA", 7: "SU"}
var wdNames = map[int]string{1: "周一", 2: "周二", 3: "周三", 4: "周四", 5: "周五", 6: "周六", 7: "周日"}

// =====================================================================
// 每周规则的实现
// =====================================================================

type Weekly struct {
	Interval int
	Weekdays []int // ISO：1=周一 … 7=周日
	Hour     int   // 触发时刻，与「周几」是**两个独立维度**
	Minute   int
}

// NewWeekly 的时刻来自「规则创建时的 trigger 时刻」，
// 不是 from 的时刻 —— from 只是「从哪一刻开始往后找」。
// 这两者的区别在第 4 节演示：周日 19:00 创建、规则时刻 20:00。
func NewWeekly(triggerAt time.Time, from time.Time, interval int, weekdays []int) Weekly {
	w := Weekly{
		Interval: interval, Weekdays: weekdays,
		Hour: triggerAt.Hour(), Minute: triggerAt.Minute(),
	}
	sort.Ints(w.Weekdays)
	_ = from
	return w
}

// Next 算出 from 之后的下一个触发日
//
// 算法（这是本卡片的核心，必须写对）：
//  1. 退到 from 所在周的周一
//  2. 把这一周里的匹配日逐个检查，≥ from 的收下
//  3. 若还没收满，往后跳 7×interval 天，回到第 2 步
//
// 关键：跳的是 7×interval 天而不是「下一周」，
// 因为 interval 决定了相位 —— 隔 2 周的话，中间那周整天都不该出现。
func (w Weekly) Next(from time.Time, limit int) []time.Time {
	var out []time.Time
	if len(w.Weekdays) == 0 {
		return nil
	}
	cur := startOfWeek(from)
	step := 0 // 已经跳了几次周
	// 最多跳 200 次，防止 interval 与 weekdays 不兼容时死循环
	for guard := 0; guard < 200 && len(out) < limit; guard++ {
		if step%w.Interval == 0 {
			for _, wd := range w.Weekdays {
				d := cur.AddDate(0, 0, wd-1)
				cand := time.Date(d.Year(), d.Month(), d.Day(),
					w.Hour, w.Minute, 0, 0, cst)
				if cand.Before(from) {
					continue
				}
				out = append(out, cand)
				if len(out) >= limit {
					return out
				}
			}
		}
		step++
		cur = cur.AddDate(0, 0, 7*w.Interval)
	}
	return out
}

func startOfWeek(t time.Time) time.Time {
	d := time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, cst)
	back := (int(d.Weekday()) + 6) % 7
	return d.AddDate(0, 0, -back)
}

func isoWeekday(t time.Time) int {
	wd := int(t.Weekday())
	if wd == 0 {
		return 7
	}
	return wd
}

