func isoWeekdayName(t time.Time) string {
	return wdNames[isoWeekday(t)]
}

func seqStr(seq []time.Time) string {
	var parts []string
	for i, t := range seq {
		if i == 0 {
			parts = append(parts, t.Format("01-02 "+"15:04"))
		} else {
			gap := int(t.Sub(seq[i-1]).Hours() / 24)
			parts = append(parts, t.Format("01-02")+fmt.Sprintf("(+%dd)", gap))
		}
	}
	return strings.Join(parts, "  ")
}

func gapStr(seq []time.Time) string {
	var parts []string
	for i := 1; i < len(seq); i++ {
		parts = append(parts, fmt.Sprintf("%d", int(seq[i].Sub(seq[i-1]).Hours()/24)))
	}
	return strings.Join(parts, " → ")
}

func dateStr(seq []time.Time) string {
	var parts []string
	for _, t := range seq {
		parts = append(parts, t.Format("01-02"))
	}
	return strings.Join(parts, ",")
}

// =====================================================================
// W31 d21：每月规则的月底陷阱 —— 1/31 → 2/28 → 3/31 的真实序列。
//
// ★ 本卡片是 S8 最重要的技术卡之一。
//
// 问题：一条规则写「每月 31 日」。2 月没有 31 日。
//       那么 2 月这一次怎么办？
//
// 有四种做法，四种都有人用：
//   A 跳过        → 2 月不发，3 月 31 日照常
//   B 顺延到月末  → 2 月 28 日发
//   C 顺延到 3/2  → 2 月没有，就推到 3 月 2 日（会与 3/31 乱序）
//   D 退到 2/28 但仍然"算一次" → 与 B 等价，但语义不同
//
// 本程序把四种做法都跑一遍，输出**真实日期序列**，
// 让你看到 1/31 → 2/28 → 3/31 这条序列到底长什么样。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 1, 15, 9, 0, 0, 0, cst)

func daysIn(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, cst).Day()
}

func clamp(y, m, d int) int {
	max := daysIn(y, m)
	if d > max {
		return max
	}
	if d < 1 {
		return 1
	}
	return d
}

type Occ struct {
	Date  time.Time
	Note  string // 说明这一天是怎么来的
	Shift bool   // 是否是顺延出来的
}

// =====================================================================
// 四种做法
// =====================================================================

// A 跳过：那个月**够不着这一天就整次不发**（2 月、4 月、6 月…全都没有 31 号）
func policySkip(from time.Time, day int, n int) []Occ {
	var out []Occ
	y, m := from.Year(), int(from.Month())
	for guard := 0; guard < 400 && len(out) < n; guard++ {
		if day <= daysIn(y, m) {
			d := time.Date(y, time.Month(m), day, from.Hour(), from.Minute(), 0, 0, cst)
			if !d.Before(from) {
				out = append(out, Occ{Date: d})
			}
		}
		y, m = nextMonth(y, m)
	}
	return out
}

// B 顺延到当月最后一天
func policyClamp(from time.Time, day int, n int) []Occ {
	var out []Occ
	y, m := from.Year(), int(from.Month())
	for len(out) < n {
		real := day
		note := ""
		shift := false
		if day > daysIn(y, m) {
			real = daysIn(y, m)
			note = fmt.Sprintf("%d 月只有 %d 天 → 顺延到 %d", m, daysIn(y, m), real)
			shift = true
		}
		d := time.Date(y, time.Month(m), real, from.Hour(), from.Minute(), 0, 0, cst)
		if !d.Before(from) {
			out = append(out, Occ{Date: d, Note: note, Shift: shift})
		}
		y, m = nextMonth(y, m)
	}
	return out
}

// C 滚到「下一个够得着的日子」：本月够不着就把**目标日**往后挪，
//
//	挪到能容纳它的那个月为止。这样会出现同月两次触发。
func policyRollForward(from time.Time, day int, n int) []Occ {
	var out []Occ
	y, m := from.Year(), int(from.Month())
	for guard := 0; guard < 400 && len(out) < n; guard++ {
		if day > daysIn(y, m) {
			// 本月装不下：把目标日推到「下个月的同一天」，
			// 但如果下个月也装不下，就继续推（示例里 1 月的 31 号会一路推到 3 月）
			note := fmt.Sprintf("%d 月装不下 %d 日 → 目标推到 %d 月 %d 日", m, day, m+1, day)
			ny, nm := nextMonth(y, m)
			d := time.Date(ny, time.Month(nm), clamp(ny, nm, day),
				from.Hour(), from.Minute(), 0, 0, cst)
			if !d.Before(from) {
				out = append(out, Occ{Date: d, Note: note, Shift: true})
			}
			// 关键：**不消费本月**，直接跳到下个月继续（于是该月会有两次）
			y, m = ny, nm
			continue
		}
		d := time.Date(y, time.Month(m), day, from.Hour(), from.Minute(), 0, 0, cst)
		if !d.Before(from) {
			out = append(out, Occ{Date: d})
		}
		y, m = nextMonth(y, m)
	}
	return out
}

// D 只在「有该日」的月份发，并把日期记为月末（等价 B，但语义是"锚定日"）
func policyLastDay(from time.Time, day int, n int) []Occ {
	var out []Occ
	y, m := from.Year(), int(from.Month())
	for len(out) < n {
		d := day
		if d > daysIn(y, m) {
			d = daysIn(y, m)
		}
		t := time.Date(y, time.Month(m), d, from.Hour(), from.Minute(), 0, 0, cst)
		if !t.Before(from) {
			out = append(out, Occ{Date: t, Shift: d != day})
		}
		y, m = nextMonth(y, m)
	}
	return out
}

func nextMonth(y, m int) (int, int) {
	m++
	if m > 12 {
		m = 1
		y++
	}
	return y, m
}

