func printSeq(label string, occ []Occ, n int) {
	fmt.Printf("  %s\n", label)
	for i, o := range occ {
		if i >= n {
			break
		}
		mark := ""
		if o.Shift {
			mark = "  ← 顺延"
		}
		fmt.Printf("    %s  %s%s\n",
			pad(o.Date.Format("2006-01-02"), 14),
			pad(wdName(o.Date), 8),
			o.Note+mark)
	}
	fmt.Println()
}

var wdNames = map[string]string{
	"Mon": "周一", "Tue": "周二", "Wed": "周三", "Thu": "周四",
	"Fri": "周五", "Sat": "周六", "Sun": "周日",
}

func wdName(t time.Time) string { return wdNames[t.Weekday().String()] }

