func occStr(occ []Occ, n int) string {
	var parts []string
	for i := 0; i < len(occ) && i < n; i++ {
		parts = append(parts, occ[i].Date.Format("01-02"))
	}
	return strings.Join(parts, ",")
}

func sortStrings(s []string) {
	for i := 0; i < len(s); i++ {
		for j := i + 1; j < len(s); j++ {
			if s[j] < s[i] {
				s[i], s[j] = s[j], s[i]
			}
		}
	}
}

// =====================================================================
// W31 d22：每年规则 —— 2 月 29 日的闰年处理。
//
// d21 讲了每月的月底陷阱。今天讲每年：**同一类问题，但更隐蔽**。
//
// 为什么更隐蔽？
//   每月的坑一年出现一次（2 月），你一定会撞上；
//   闰年的坑**四年才出现一次**（2028 vs 2026）—— 你写完代码、
//     测完一轮、全绿上线，然后四年后才在生产上炸。
//
// 本程序跑出 2026 → 2032 的完整序列，证明：
//   · yearly:02-29 四年才触发一次
//   · yearly:02-28 会**每年**触发，但 2/28 在闰年不是月末
//   · 两种表达法在 2028 年分道扬镳
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 1, 15, 9, 0, 0, 0, cst)

func daysIn(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, cst).Day()
}

func isLeap(y int) bool {
	// 闰年规则：能被 4 整除但不能被 100 整除，或能被 400 整除
	return (y%4 == 0 && y%100 != 0) || y%400 == 0
}

func clamp(y, m, d int) int {
	max := daysIn(y, m)
	if d > max {
		return max
	}
	if d < 1 {
		return 1
	}
	return d
}

type Occ struct {
	Date  time.Time
	Note  string
	Shift bool
}

// =====================================================================
// 每年规则的三种实现
// =====================================================================

// P1 严格：只在闰年的 2/29 触发（yearly:02-29）
func yearlyLeapDay(from time.Time, n int) []Occ {
	var out []Occ
	y := from.Year()
	for guard := 0; guard < 500 && len(out) < n; guard++ {
		if isLeap(y) {
			d := time.Date(y, 2, 29, from.Hour(), from.Minute(), 0, 0, cst)
			if !d.Before(from) {
				out = append(out, Occ{Date: d, Note: fmt.Sprintf("%d 是闰年 → 2/29 存在", y)})
			}
		}
		y++
	}
	return out
}

// P2 夹取：yearly:02-29 遇到平年顺延到 2/28（**这是错的语义**）
func yearlyClamp(from time.Time, n int) []Occ {
	var out []Occ
	y := from.Year()
	for guard := 0; guard < 500 && len(out) < n; guard++ {
		real := clamp(y, 2, 29)
		d := time.Date(y, 2, real, from.Hour(), from.Minute(), 0, 0, cst)
		note := ""
		shift := false
		if real != 29 {
			note = fmt.Sprintf("%d 不是闰年 → 顺延到 2/%d", y, real)
			shift = true
		}
		if !d.Before(from) {
			out = append(out, Occ{Date: d, Note: note, Shift: shift})
		}
		y++
	}
	return out
}

// P3 每年 2/28（yearly:02-28）—— 每年都触发，闰年也不例外
func yearlyFeb28(from time.Time, n int) []Occ {
	var out []Occ
	y := from.Year()
	for guard := 0; guard < 500 && len(out) < n; guard++ {
		d := time.Date(y, 2, 28, from.Hour(), from.Minute(), 0, 0, cst)
		note := ""
		if isLeap(y) {
			note = fmt.Sprintf("%d 是闰年 → 2/29 不在这一天", y)
		}
		if !d.Before(from) {
			out = append(out, Occ{Date: d, Note: note})
		}
		y++
	}
	return out
}

// P4 每年 2 月最后一天（yearly:last-02）—— 闰年是 29，平年是 28
func yearlyFebLast(from time.Time, n int) []Occ {
	var out []Occ
	y := from.Year()
	for guard := 0; guard < 500 && len(out) < n; guard++ {
		real := daysIn(y, 2)
		d := time.Date(y, 2, real, from.Hour(), from.Minute(), 0, 0, cst)
		if !d.Before(from) {
			out = append(out, Occ{Date: d,
				Note: fmt.Sprintf("%d 闰 → 2/%d", y, real)})
		}
		y++
	}
	return out
}

// P5 每年 3/1（yearly:03-01）—— 每年都触发，不受闰年影响（对照组）
func yearlyMar1(from time.Time, n int) []Occ {
	var out []Occ
	y := from.Year()
	for guard := 0; guard < 500 && len(out) < n; guard++ {
		d := time.Date(y, 3, 1, from.Hour(), from.Minute(), 0, 0, cst)
		if !d.Before(from) {
			out = append(out, Occ{Date: d})
		}
		y++
	}
	return out
}

