	for _, b := range bad {
		got := time.Date(b.Y, time.Month(b.M), b.D, 9, 0, 0, 0, cst)
		mark := ""
		if got.Day() != b.D || got.Month() != time.Month(b.M) {
			mark = "  ← 被进位了"
		}
		fmt.Printf("    time.Date(%d, %2d, %2d, ...) = %s   %s%s\n",
			b.Y, b.M, b.D, got.Format("2006-01-02"), pad(b.Want, 16), mark)
	}
	fmt.Println()
	fmt.Println("  没有一行报错。全部静默给了错误的答案。")
	fmt.Println("  所以「构造日期前先检查」是硬要求：")
	fmt.Println("    if d > daysIn(y, m) { ... }")
	fmt.Println("  这一行代码在 d21 的 clamp 里、在 d22 的 isLeap 里，各出现一次。")
	fmt.Println()

	// ---------------- 10. 小结 ----------------
	fmt.Println("=== 10. W31 d22 小结 ===")
	fmt.Println()
	fmt.Println("  ① 闰年判定用 daysIn(y,2)==29，别自己写公式（2000/2100 是试金石）")
	fmt.Println("  ② yearly:02-29 严格版四年触发一次；夹取版每年都触发 —— 语义完全不同")
	fmt.Println("  ③ 「每年 2/28」≠「每年 2 月末」，闰年差一天")
	fmt.Println("  ④ **yearly 不做 clamp** —— 够不着就跳过，clamp 会偷换语义")
	fmt.Println("  ⑤ time.Date 会静默进位，构造前必须检查 d ≤ daysIn(y,m)")
	fmt.Println("  ⑥ 闰年判断只能在应用层，数据库 CHECK 管不了「这一年有没有 2/29」")
	fmt.Println("  ⑦ 测试必须显式构造闰年与非闰年两套数据，不能用 time.Now().Year()")
	fmt.Println("  ⑧ 自测 5/5 通过（本日实测）")
	fmt.Println("  ⑨ 显示日期一律用 Format(\"2006-01-02\") —— 短格式会串位")
	fmt.Println()
	fmt.Println("  明天讲跳过与顺延：节假日跳过 vs 顺延到下一天，两个语义差别。")
}

func yesNo(b bool) string {
	if b {
		return "是"
	}
	return "否"
}

func fullStr(occ []Occ, n int) string {
	var parts []string
	for i := 0; i < len(occ) && i < n; i++ {
		parts = append(parts, occ[i].Date.Format("2006-01-02"))
	}
	return strings.Join(parts, ",")
}

// =====================================================================
// W31 d23：跳过与顺延 —— 节假日跳过 vs 顺延到下一天。
//
// PRD 3.9.2 的「跳过、顺延」是最后两个词，也是最容易被混为一谈的两个。
//
// 核心区别一句话：
//   跳过 skip   = **这一次没有**（不产生触发）
//   顺延 shift  = **这一次挪到别的时间**（产生触发，只是换了时刻）
//
// 本程序拿同一个场景（2026 春节 2/17 大年初一）跑三种策略，
// 输出真实日期序列，然后回答「为什么不能默认选一个」。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 1, 15, 9, 0, 0, 0, cst)

func daysIn(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, cst).Day()
}

// =====================================================================
// 节假日表（2026 年，简化版，只列本卡片用到的）
// =====================================================================

type Holiday struct {
