}

func isHoliday(t time.Time) (bool, string) {
	n, ok := holidayMap[t.Format("2006-01-02")]
	return ok, n
}

func isMakeup(t time.Time) (bool, string) {
	n, ok := makeupDays[t.Format("2006-01-02")]
	return ok, n
}

// =====================================================================
// 三种策略
// =====================================================================

type Occ struct {
	Date    time.Time
	Action  string // 正常 / 跳过 / 顺延
	Because string // 原因
	Origin  time.Time
	Dropped bool // 是否不产生触发
}

const (
	ActNormal = "正常触发"
	ActSkip   = "跳过（不产生触发）"
	ActShift  = "顺延（挪到这天）"
)

// S0 无策略：撞上就撞上
func policyNone(rule func(time.Time, time.Time) time.Time, from time.Time, n int) []Occ {
	var out []Occ
	t := from
	for i := 0; i < n; i++ {
		out = append(out, Occ{Date: t, Action: ActNormal, Origin: t})
		t = rule(t, from)
	}
	return out
}

// S1 跳过：落在节假日就整次不发
func policySkipHoliday(rule func(time.Time, time.Time) time.Time, from time.Time, n int) []Occ {
	var out []Occ
	t := from
	for i := 0; i < n; i++ {
		if on, name := isHoliday(t); on {
			out = append(out, Occ{Date: t, Action: ActSkip,
				Because: "落在「" + name + "」", Origin: t, Dropped: true})
		} else if mk, name := isMakeup(t); mk {
			out = append(out, Occ{Date: t, Action: ActNormal,
				Because: name + "，不跳过", Origin: t})
		} else {
			out = append(out, Occ{Date: t, Action: ActNormal, Origin: t})
		}
		t = rule(t, from)
	}
	return out
}

// S2 顺延：落在节假日就往后挪一天，挪到不撞为止
func policyShiftHoliday(rule func(time.Time, time.Time) time.Time, from time.Time, n int) []Occ {
	var out []Occ
	t := from
	for i := 0; i < n; i++ {
		origin := t
		cur := t
		shifts := 0
		for {
			on, _ := isHoliday(cur)
			mk, _ := isMakeup(cur)
			if !on || mk {
				break
			}
			cur = cur.AddDate(0, 0, 1)
			shifts++
			if shifts > 7 {
				break // 安全阀：连撞 7 天就放弃
			}
		}
		if shifts == 0 {
			out = append(out, Occ{Date: t, Action: ActNormal, Origin: origin})
		} else {
			_, name := isHoliday(origin)
			out = append(out, Occ{Date: cur, Action: ActShift,
				Because: fmt.Sprintf("原定 %s（%s），往后 %d 天", origin.Format("01-02"), name, shifts),
				Origin:  origin})
		}
		t = rule(t, from)
	}
	return out
}

// =====================================================================
// 规则函数
// =====================================================================

// monthlyRule 返回「下一次」函数。
// ⚠ Go 里 (a, b) 和 (b, a) 都是合法的调用签名，写错了编译器不报错 ——
//
//	这里显式把参数名写清楚：cur 是当前时刻，返回值是下一次。
func monthlyRule(day int) func(cur, from time.Time) time.Time {
	return func(cur, _ time.Time) time.Time {
		y, m := cur.Year(), int(cur.Month())+1
		if m > 12 {
			m = 1
			y++
		}
		d := day
		if d > daysIn(y, m) {
			d = daysIn(y, m)
		}
		return time.Date(y, time.Month(m), d, cur.Hour(), cur.Minute(), 0, 0, cst)
	}
}

func dailyRule() func(cur, from time.Time) time.Time {
	return func(cur, _ time.Time) time.Time {
		return cur.AddDate(0, 0, 1)
	}
}

