func printOcc(label string, occ []Occ, n int) {
	fmt.Printf("  %s\n", label)
	real := 0
	shown := 0
	for _, o := range occ {
		if !o.Dropped {
			real++
		}
		if shown >= n {
			continue
		}
		shown++
		fmt.Printf("    %s %s %s\n",
			pad(o.Date.Format("2006-01-02"), 14),
			pad(o.Action, 22),
			pad(o.Because, 44))
	}
	fmt.Printf("    → 共 %d 条规则，其中 %d 次真正触发，%d 次跳过\n\n",
		len(occ), real, len(occ)-real)
}

