// realStr 只取真正触发的日期
func realStr(occ []Occ, n int) string {
	var parts []string
	for _, o := range occ {
		if o.Dropped {
			continue
		}
		if len(parts) >= n {
			break
		}
		parts = append(parts, o.Date.Format("01-02"))
	}
	return strings.Join(parts, ",")
}

