// W31 d24：W31 收口 —— 把 d19-d23 拼成完整的周期规则引擎。
//
// 前五天分别讲了六个维度、每周、每月、每年、跳过顺延。
// 今天把它们合起来：**一个 parse 函数 + 一个 next 函数 + 一个 case 表**。
//
// 这份代码就是 tech-plan 里「周期规则引擎」的最小可用形态，
// 也是 W32 d25（repeat 存储格式）与 d26（next_at）的输入。
//
// 收口做三件事：
//   ① 完整引擎：七种表达法 + 三种月底策略 + 三种例外策略
//   ② 引擎自测：全部 case 一张表，逐条断言
//   ③ 故意破坏：把「闰年判定」写错，看哪几条断言会红
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)

func daysIn(y, m int) int {
	return time.Date(y, time.Month(m)+1, 0, 0, 0, 0, 0, cst).Day()
}

func isLeap(y int) bool { return daysIn(y, 2) == 29 }

// =====================================================================
// ① 完整引擎
// =====================================================================

type Freq int

const (
	FreqNone Freq = iota
	FreqDaily
	FreqWeekly
	FreqMonthly
	FreqYearly
)

type Rule struct {
	Freq     Freq
	Interval int
	Weekdays []int // 1=MO … 7=SU
	MonthDay int   // 1..31；0 = 当月最后一天
	IsLast   bool
	Month    int
	LeapOnly bool
	// 例外策略
	SkipHoliday bool
	SkipWeekend bool
	ShiftDays   int // >0 = 顺延天数；0 = 不顺延
	Hour, Min   int
	// Anchor 是规则的「相位基准」：monthly/yearly 的 interval 从这里开始数
	AnchorYear  int
	AnchorMonth int
}

// Parse 解析 repeat 字符串。d25 会讲这个字符串本身的格式设计。
func Parse(expr string, hour, min int) Rule {
	r := Rule{Interval: 1, Hour: hour, Min: min}
	if expr == "" || expr == "once" {
		r.Freq = FreqNone
		return r
	}
	// 先剥掉例外后缀
	if i := strings.Index(expr, ";"); i >= 0 {
		suffix := expr[i+1:]
		expr = expr[:i]
		for _, part := range strings.Split(suffix, ";") {
			switch {
			case part == "skip=holiday":
				r.SkipHoliday = true
			case part == "skip=weekend":
				r.SkipWeekend = true
			case strings.HasPrefix(part, "shift="):
				d := atoi(strings.TrimSuffix(strings.TrimPrefix(part, "shift=+"), "d"))
				r.ShiftDays = d
			}
		}
	}
	switch {
	case expr == "daily":
		r.Freq = FreqDaily
	case strings.HasPrefix(expr, "weekly:"):
		r.Freq = FreqWeekly
		codes := map[string]int{"MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6, "SU": 7}
		for _, c := range strings.Split(strings.TrimPrefix(expr, "weekly:"), ",") {
			r.Weekdays = append(r.Weekdays, codes[c])
		}
		sort.Ints(r.Weekdays)
	case strings.HasPrefix(expr, "monthly:last"):
		r.Freq, r.IsLast, r.MonthDay = FreqMonthly, true, 0
	case strings.HasPrefix(expr, "monthly:"):
		r.Freq = FreqMonthly
		r.MonthDay = atoi(strings.TrimPrefix(expr, "monthly:"))
	case expr == "yearly:02-29":
		r.Freq, r.Month, r.LeapOnly = FreqYearly, 2, true
	case strings.HasPrefix(expr, "yearly:last-"):
		r.Freq = FreqYearly
		r.Month = atoi(strings.TrimPrefix(expr, "yearly:last-"))
		r.MonthDay = 0 // 0 = 当月最后一天
	case strings.HasPrefix(expr, "yearly:"):
		r.Freq = FreqYearly
		mp := strings.Split(strings.TrimPrefix(expr, "yearly:"), "-")
		r.Month = atoi(mp[0])
		if len(mp) > 1 {
			r.MonthDay = atoi(mp[1])
		}
	}
	return r
}

// ---- 节假日表（2026，简化）----
var holidayDays = map[string]bool{
	"2026-02-16": true, "2026-02-17": true, "2026-02-18": true,
	"2026-04-06": true, "2026-05-01": true, "2026-06-19": true,
	"2026-10-01": true, "2026-10-02": true, "2026-10-03": true,
}

func isHoliday(t time.Time) bool { return holidayDays[t.Format("2006-01-02")] }
func isWeekend(t time.Time) bool { return t.Weekday() == time.Saturday || t.Weekday() == time.Sunday }

func (r Rule) blocked(t time.Time) bool {
	if r.SkipHoliday && isHoliday(t) {
		return true
	}
	if r.SkipWeekend && isWeekend(t) {
		return true
	}
	return false
}

// Occurrence 是一次触发
type Occurrence struct {
	Date    time.Time
	Skipped bool
	Shifted bool
	Origin  time.Time
	SkipWhy string
}

// Next 算出 from 之后的下一个触发日（含例外处理）
func (r Rule) Next(from time.Time) (Occurrence, bool) {
	// 例外处理：先看 from 本身是否被跳过
	// 简化模型：从 from 开始找，最多找 500 次
	cand := from
	for i := 0; i < 500; i++ {
		hit := r.matches(cand)
		if hit {
			occ := Occurrence{Date: cand, Origin: cand}
			if r.blocked(cand) {
				if r.ShiftDays > 0 {
					// 顺延
					shifted := cand
					for k := 0; k < r.ShiftDays; k++ {
						shifted = shifted.AddDate(0, 0, 1)
						if !r.blocked(shifted) {
							break
						}
					}
					occ.Date = shifted
					occ.Shifted = true
					occ.Origin = cand
					return occ, true
				}
				occ.Skipped = true
				if isHoliday(cand) {
					occ.SkipWhy = "节假日"
				} else {
					occ.SkipWhy = "周末"
				}
				// 跳过：从这次往后继续找
				cand = r.advance(cand)
				continue
			}
			return occ, true
		}
		cand = r.advance(cand)
	}
	return Occurrence{}, false
}

// matches 判断某个时刻是否符合规则（不含例外）
func (r Rule) matches(t time.Time) bool {
	switch r.Freq {
	case FreqNone:
		return true
	case FreqDaily:
		return true
	case FreqWeekly:
		// 相位：与 Anchor 所在周的周数差必须是 Interval 的倍数
		if (weekIndex(t)-weekIndex(anchorOf(r)))%r.Interval != 0 {
			return false
		}
		wd := int(t.Weekday())
		if wd == 0 {
			wd = 7
		}
		for _, w := range r.Weekdays {
			if w == wd {
				return true
			}
		}
		return false
	case FreqMonthly:
		// 相位：从 AnchorMonth 起，每 Interval 个月才匹配一次
		if !r.monthPhaseOK(t) {
			return false
		}
		want := r.MonthDay
		if r.IsLast {
			want = daysIn(t.Year(), int(t.Month()))
		} else if want > daysIn(t.Year(), int(t.Month())) {
			// clamp（d21）：31 号在 2 月顺延到月末。
			// 这一行是 monthly:31 能跑通的关键 —— 没有它，
			// 2 月永远匹配不上，序列直接少一个月。
			want = daysIn(t.Year(), int(t.Month()))
		}
		return t.Day() == want
	case FreqYearly:
		// 相位：从 AnchorYear 起，每 Interval 年才匹配一次
		if (t.Year()-r.AnchorYear)%r.Interval != 0 {
			return false
		}
		if int(t.Month()) != r.Month {
			return false
		}
		if r.LeapOnly {
			return t.Day() == 29 && isLeap(t.Year())
		}
		if r.MonthDay > 0 {
			return t.Day() == r.MonthDay
		}
		return t.Day() == daysIn(t.Year(), int(t.Month()))
	}
	return false
}

func anchorOf(r Rule) time.Time {
	return time.Date(r.AnchorYear, time.Month(r.AnchorMonth), 1, r.Hour, r.Min, 0, 0, cst)
}

// monthPhaseOK 判断 t 所在月是否命中 interval 的相位
func (r Rule) monthPhaseOK(t time.Time) bool {
	diff := (t.Year()-r.AnchorYear)*12 + (int(t.Month()) - r.AnchorMonth)
	return ((diff%r.Interval)+r.Interval)%r.Interval == 0
}

// weekIndex 返回该日期所在 ISO 周的周序号（以锚点年为基准的粗略实现）
func weekIndex(t time.Time) int {
	d := time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, cst)
	back := (int(d.Weekday()) + 6) % 7
	monday := d.AddDate(0, 0, -back)
	// 用「距 2026-01-01 的天数 / 7」做粗略周序号，够本程序用
	ref := time.Date(2026, 1, 5, 0, 0, 0, 0, cst) // 2026-01-05 是周一
	return int(monday.Sub(ref).Hours() / 24 / 7)
}

// advance 从 t 往前推「一个步进单位」
func (r Rule) advance(t time.Time) time.Time {
	switch r.Freq {
	case FreqDaily:
		return t.AddDate(0, 0, r.Interval)
	case FreqWeekly:
		// 推到下一个匹配日
		for i := 1; i <= 7; i++ {
			c := t.AddDate(0, 0, i)
			if r.matches(c) {
				return c
			}
		}
		return t.AddDate(0, 0, 7)
	case FreqMonthly:
		y, m := t.Year(), int(t.Month())+r.Interval
		for m > 12 {
			m -= 12
			y++
		}
		want := r.MonthDay
		if r.IsLast {
			want = daysIn(y, m)
		}
		if want > daysIn(y, m) {
			want = daysIn(y, m) // clamp
		}
		return time.Date(y, time.Month(m), want, r.Hour, r.Min, 0, 0, cst)
	case FreqYearly:
		return time.Date(t.Year()+r.Interval, time.Month(r.Month), r.MonthDay, r.Hour, r.Min, 0, 0, cst)
	}
	return t.AddDate(0, 0, 1)
}

// Sequence 算出接下来 n 次（被跳过的也计入占位，但 RealStr 会过滤掉）
//
// 实现说明：这里用「日粒度扫描 + 全局上限」而不是递归调用 Next。
// 原因：Next 内部会跳过被跳过的日期并继续找，如果外层又调 Next，
// 两层循环叠起来在 interval 较大的规则上会死循环 ——
// 而且「扫描上限」这个保险只有一层才有效。
func (r Rule) Sequence(from time.Time, n int) []Occurrence {
	if r.AnchorYear == 0 {
		r.AnchorYear = from.Year()
		r.AnchorMonth = int(from.Month())
	}
	var out []Occurrence
	cur := from
	for i := 0; i < 4000 && len(out) < n; i++ {
		if !r.matches(cur) {
			cur = cur.AddDate(0, 0, 1)
			// 时刻对齐到规则时刻（weekly/monthly 靠 matches 判天，hour 另行处理）
			cur = time.Date(cur.Year(), cur.Month(), cur.Day(), r.Hour, r.Min, 0, 0, cst)
			continue
		}
		occ := Occurrence{Date: cur, Origin: cur}
		if r.blocked(cur) {
			if r.ShiftDays > 0 {
				sh := cur
				for k := 0; k < r.ShiftDays; k++ {
					sh = sh.AddDate(0, 0, 1)
					if !r.blocked(sh) {
						break
					}
				}
				occ.Date = sh
				occ.Shifted = true
			} else {
				occ.Skipped = true
				if isHoliday(cur) {
					occ.SkipWhy = "节假日"
				} else {
					occ.SkipWhy = "周末"
				}
			}
		}
		out = append(out, occ)
		// 无论触发/跳过/顺延，扫描指针都只前进一天 —— 避免死循环
		cur = time.Date(cur.Year(), cur.Month(), cur.Day(), r.Hour, r.Min, 0, 0, cst).AddDate(0, 0, 1)
	}
	return out
}

