func parseT(s string) time.Time {
	// "2026-03-18 08:00"
	// ⚠ fmt.Sscanf 一次只能填一个变量，逐个调用才行 ——
	//   Sscanf(s, "%d", &y, &m) 会把 m 留在未定义状态。
	parts := strings.Fields(s)
	dp := strings.Split(parts[0], "-")
	tp := strings.Split(parts[1], ":")
	y := atoi(dp[0])
	mo := atoi(dp[1])
	day := atoi(dp[2])
	h := atoi(tp[0])
	mi := atoi(tp[1])
	return time.Date(y, time.Month(mo), day, h, mi, 0, 0, cst)
}

func atoi(s string) int {
	n := 0
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

// RealStr 只取真正触发的日期
func RealStr(r Rule, from time.Time, n int) string {
	occ := r.Sequence(from, n)
	var parts []string
	cnt := 0
	for _, o := range occ {
		if o.Skipped {
			continue
		}
		if cnt >= n {
			break
		}
		if r.Freq == FreqYearly {
			// 年度规则的日期必须带年份，否则 2028/2032/2036 看起来一模一样
			if o.Shifted {
				parts = append(parts, o.Date.Format("2006-01-02")+"*")
			} else {
				parts = append(parts, o.Date.Format("2006-01-02"))
			}
		} else {
			if o.Shifted {
				parts = append(parts, o.Date.Format("01-02")+"*")
			} else {
				parts = append(parts, o.Date.Format("01-02"))
			}
		}
		cnt++
	}
	return strings.Join(parts, ",")
}

