// =====================================================================
// W32 d25：repeat 字段的存储格式 —— 为什么用字符串不用 JSONB 列。
//
// PRD 3.9.5 明令：
//   「周期任务与重复规则语义沿用三张表既有的 repeat 字段，
//     **不得另立 calendar_recurrence 之类的重复规则表**」
//
// 所以 repeat 是三张表里的一列 VARCHAR(64)。今天要回答：
//   ① 为什么是字符串而不是 JSONB / 结构化多列？
//   ② 字符串的三种表达法怎么选？
//   ③ VARCHAR(64) 够不够？装不下怎么办？
//
// 本程序把五种候选格式都跑一遍，用**同一组周期规则**逐个验证：
// 能不能表达、能不能 CHECK、能排序吗、能被人读吗。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

