	{"闰年 2 月 29 日", "yearly:02-29"},
}

// ---- 格式 A：紧凑字符串（本项目采用）----
func fmtA(r string) string { return r }

// ---- 格式 B：JSONB（结构化，最灵活）----
func fmtB(r string) string {
	freq, arg := r, ""
	if i := strings.Index(r, ":"); i >= 0 {
		freq, arg = r[:i], r[i+1:]
	}
	// 后缀拆出来（every / skip / shift）
	suffix := ""
	body := r
	if i := strings.Index(r, ";"); i >= 0 {
		body, suffix = r[:i], r[i+1:]
		if j := strings.Index(body, ":"); j >= 0 {
			freq, arg = body[:j], body[j+1:]
		} else {
			freq, arg = body, ""
		}
	}
	out := `{"freq":"` + freq + `"`
	switch freq {
	case "weekly":
		out += `,"by":["` + strings.ReplaceAll(arg, ",", `","`) + `"]`
	case "monthly":
		if arg == "last" {
			out += `,"bymonthday":"last"`
		} else {
			out += `,"bymonthday":` + arg
		}
	case "yearly":
		out += `,"bymonth":"` + strings.SplitN(arg, "-", 2)[0] + `"`
		out += `,"bymonthday":"` + strings.SplitN(arg, "-", 2)[1] + `"`
	}
	if suffix != "" {
		for _, kv := range strings.Split(suffix, ";") {
			switch {
			case strings.HasPrefix(kv, "every="):
				out += `,"interval":` + strings.TrimPrefix(kv, "every=")
			case strings.HasPrefix(kv, "skip="):
				out += `,"skip":"` + strings.TrimPrefix(kv, "skip=") + `"`
			case strings.HasPrefix(kv, "shift="):
				out += `,"shift":"` + strings.TrimPrefix(kv, "shift=") + `"`
			}
		}
	}
	return out + `}`
}

// ---- 格式 C：逗号分隔的全数值（ICal RRULE 风格）----
func fmtC(r string) string {
	m := map[string]string{"daily": "FREQ=DAILY"}
	switch {
	case strings.HasPrefix(r, "weekly:MO,WE,FR"):
		m[r] = "FREQ=WEEKLY;BYDAY=MO,WE,FR"
	case strings.HasPrefix(r, "weekly:MO;every=2"):
		m[r] = "FREQ=WEEKLY;INTERVAL=2;BYDAY=MO"
	case r == "monthly:20":
		m[r] = "FREQ=MONTHLY;BYMONTHDAY=20"
	case r == "monthly:last":
		m[r] = "FREQ=MONTHLY;BYMONTHDAY=-1"
	case r == "monthly:31":
		m[r] = "FREQ=MONTHLY;BYMONTHDAY=31"
	case r == "yearly:03-20":
		m[r] = "FREQ=YEARLY;BYMONTH=3;BYMONTHDAY=20"
	case r == "yearly:02-29":
		m[r] = "FREQ=YEARLY;BYMONTH=2;BYMONTHDAY=29"
	}
	return m[r]
}

// ---- 格式 D：结构化多列（拆成 5 列）----
func fmtD(r string) string {
	freq, arg1, arg2 := "", "", ""
	switch {
	case r == "daily":
		freq = "daily"
	case strings.HasPrefix(r, "weekly:"):
		freq = "weekly"
		body := r
		if i := strings.Index(r, ";"); i >= 0 {
			body = r[:i]
			if j := strings.Index(r[i+1:], "every="); j >= 0 {
				arg2 = strings.TrimPrefix(r[i+1+j:], "every=")
			}
		}
		arg1 = strings.TrimPrefix(body, "weekly:")
	default:
		sp := strings.SplitN(r, ":", 2)
		freq = sp[0]
		arg1 = sp[1]
	}
	return fmt.Sprintf("freq=%-8s arg1=%-10s arg2=%s", freq, arg1, arg2)
}

// ---- 格式 E：位图（用 int64 编码周几）----
func fmtE(r string) string {
	body := r
	if i := strings.Index(r, ";"); i >= 0 {
		body = r[:i]
	}
	if !strings.HasPrefix(body, "weekly:") {
		return "freq=other（位图编不了 monthly:31 / yearly:02-29）"
	}
	arg := strings.TrimPrefix(body, "weekly:")
	var mask int64
	codes := []string{"MO", "TU", "WE", "TH", "FR", "SA", "SU"}
	for _, c := range strings.Split(arg, ",") {
		for i, cc := range codes {
			if c == cc {
				mask |= 1 << uint(i)
			}
		}
	}
	extra := ""
	if i := strings.Index(r, ";every="); i >= 0 {
		extra = " every=" + strings.TrimPrefix(r[i+1:], "every=")
	}
	return fmt.Sprintf("freq=weekly mask=0b%s%s", bits(mask), extra)
}

// bits 按 MO→SU 的顺序输出位（bit0=MO）
func bits(m int64) string {
	var sb strings.Builder
	for i := 0; i < 7; i++ {
		if m&(1<<uint(i)) != 0 {
			sb.WriteByte('1')
		} else {
			sb.WriteByte('0')
		}
	}
	return sb.String()
}

