// =====================================================================
// W32 d26：为什么要存 next_at 而不是每次从头算。
//
// 主线问题：到期扫描每分钟跑一次，它怎么知道「哪些提醒该发了」？
//
// 两种方案：
//   A 每次从头算   —— 扫全表，对每条规则算「上次触发到现在该触发几次」
//   B 存 next_at  —— 索引里直接比 now，命中即触发
//
// B 的理由不只是快，更是三条工程上的硬需求：
//   ① 到达率 ≥99.9%（PRD 3.9.7）—— 扫描延迟必须可控
//   ② 幂等与可重放 —— 触发过的必须有据可查
//   ③ 补漏 —— 停机期间漏掉的不能丢
//
// 本程序把两种方案都跑一遍，输出真实的时间代价与正确性差异。
// =====================================================================

package main

import (
	"fmt"
	"strings"
	"time"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

var cst = time.FixedZone("CST", 8*3600)
var base = time.Date(2026, 3, 18, 9, 0, 0, 0, cst)

func at(dayOffset, h, m int) time.Time {
	d := base.AddDate(0, 0, dayOffset)
	return time.Date(d.Year(), d.Month(), d.Day(), h, m, 0, 0, cst)
}

func pt(t time.Time) *time.Time { return &t }

// =====================================================================
// 数据：20 条提醒，next_at 分布在过去 3 小时到未来 7 天
// =====================================================================

type Reminder struct {
	ID      string
	Repeat  string
	Trigger time.Time
	Advance int // 提前量（分钟）
	NextAt  *time.Time
	Status  string
	HasNext bool // next_at 是否已维护
}

var reminders = build()

func build() []Reminder {
	var rs []Reminder
	add := func(id, rep string, trig time.Time, adv int, next *time.Time, status string) {
		rs = append(rs, Reminder{
			ID: id, Repeat: rep, Trigger: trig, Advance: adv,
			NextAt: next, Status: status, HasNext: next != nil,
		})
	}
	// 已到期的 6 条（next_at 在过去）
	add("rem_01", "monthly:20", at(2, 9, 0), 60, pt(at(-2, 8, 0)), "active")
	add("rem_02", "daily", at(0, 8, 0), 30, pt(at(0, 7, 30)), "active")
	add("rem_03", "weekly:MO,WE,FR", at(1, 7, 0), 0, pt(at(-1, 7, 0)), "active")
	add("rem_04", "yearly:03-20", at(0, 10, 0), 1440, pt(at(-1, 10, 0)), "active")
	add("rem_05", "monthly:last", at(0, 12, 0), 0, pt(at(-1, 12, 0)), "active")
	add("rem_06", "once", at(0, 9, 30), 15, pt(at(0, 9, 15)), "active")
	// 暂停的 2 条（不该触发）
	add("rem_07", "daily", at(1, 9, 0), 60, pt(at(-1, 8, 0)), "paused")
	add("rem_08", "monthly:20", at(2, 9, 0), 0, nil, "paused")
	// 未来的 8 条
	add("rem_09", "daily", at(1, 21, 30), 30, pt(at(0, 21, 0)), "active")
	add("rem_10", "weekly:MO,WE,FR", at(3, 7, 0), 0, pt(at(1, 7, 0)), "active")
	add("rem_11", "monthly:20", at(2, 9, 0), 1440, pt(at(1, 9, 0)), "active")
	add("rem_12", "monthly:31", at(6, 9, 0), 60, pt(at(6, 8, 0)), "active")
	add("rem_13", "yearly:02-29", at(700, 9, 0), 0, pt(at(700, 9, 0)), "active")
	add("rem_14", "weekly:SA,SU", at(2, 8, 0), 0, pt(at(2, 8, 0)), "active")
	add("rem_15", "daily", at(1, 8, 0), 15, pt(at(7, 7, 45)), "active")
	add("rem_16", "monthly:1", at(9, 9, 0), 0, pt(at(9, 9, 0)), "active")
	// **next_at 未维护的 4 条（方案 A 的场景：靠从头算）
	add("rem_17", "monthly:20", at(2, 9, 0), 60, nil, "active")
	add("rem_18", "weekly:MO,WE,FR", at(1, 7, 0), 0, nil, "active")
	add("rem_19", "daily", at(0, 21, 30), 30, nil, "active")
	add("rem_20", "yearly:03-20", at(0, 10, 0), 0, nil, "active")
	return rs
}

func main() {
	fmt.Println("=== W32 d26 · 为什么要存 next_at 而不是每次从头算 ===")
	fmt.Println()
	fmt.Printf("  基准时刻：%s\n", base.Format("2006-01-02 15:04"))
	_nDue := 0
	_nPaused := 0
	for _, r := range reminders {
		if r.Status == "paused" {
			_nPaused++
		}
		if r.NextAt != nil && !r.NextAt.After(base) && r.Status == "active" {
			_nDue++
		}
	}
	fmt.Printf("  数据：%d 条提醒（%d 条已到期 + %d 条暂停 + %d 条未来 + 4 条 next_at 未维护）\n",
