func countDue() int {
	n := 0
	for _, r := range reminders {
		if r.NextAt != nil && !r.NextAt.After(base) && r.Status == "active" {
			n++
		}
	}
	return n
}

func scanForB() int {
	n := 0
	for _, r := range reminders {
		if r.Status == "active" && r.NextAt != nil && !r.NextAt.After(base) {
			n++
		}
	}
	return n
}

// =====================================================================
// W32 d29：降级词 —— calendar 恒启用恒出生，不可达时只记「暂不可用」。
//
// PRD 3.9.7 的降级词例外原文：
//   「`calendar` 恒启用、恒出生，因此 ㉙ 四降级词中的「未启用」「即将上线」
//     对它**不适用**，服务不可达时只记「**暂不可用**」
//     （不得因其不可达而误判为未挂载面）」
//
// 四降级词（tech-plan §7.6）：
//   未启用   本家庭没挂载这个面（homeos_family_module 无行）
//   即将上线 这个面还没出生（服务不存在）
//   暂不可用 面已启用，但本次服务不可达或分包校验失败
//   依赖未就绪 本面可用，但它依赖的另一面没出生
//
// 本程序把四个词 × 三个域 = 12 种组合真跑一遍，逐个判定该用哪个词，
// 并演示「误判」的后果 —— 这正是 PRD 要禁止的。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func pad(s string, w int) string {
	length := 0
	for _, r := range s {
		if r > 0x2E80 {
			length += 2
		} else {
			length++
		}
	}
	n := w - length
	if n <= 0 {
		return s
	}
	return s + strings.Repeat(" ", n)
}

// =====================================================================
// 四个降级词
// =====================================================================

type DegradeWord struct {
	Word    string
	Meaning string
	// 触发条件
	ModuleRow bool // homeos_family_module 有行？
	ServiceUp bool // 服务可达？
	Born      bool // 服务已出生（部署了）？
}

var words = []DegradeWord{
	{"未启用", "本家庭没挂载这个面", false, true, true},
	{"即将上线", "这个面还没出生（服务不存在）", false, false, false},
	{"暂不可用", "面已启用，但本次服务不可达或分包校验失败", true, false, true},
	{"依赖未就绪", "本面可用，但它依赖的另一面没出生", true, true, true},
}

// 域的固有属性
type Domain struct {
	Code       string
	SysLevel   bool   // 系统级面：恒启用恒出生
	CanOff     bool   // 可停用
	Dependency string // 依赖的域（空 = 无）
	ServiceUp  bool
	ModuleRow  bool
	PagesOK    bool // 分包校验是否通过
	DBOK       bool // 数据库是否可达
}

var domains = []Domain{
	{"homeos", true, false, "", true, false, true, true},
	{"calendar", true, false, "", false, false, true, false}, // 服务不可达！
	{"finance", false, true, "", true, true, true, true},
}

// =====================================================================
// 判定函数：给定状态返回该用哪个降级词
// =====================================================================

type State struct {
	ServiceReachable bool
	ModuleEnabled    bool
	ServiceDeployed  bool
	DependencyOK     bool
}

// Decide 判定该用哪个降级词
//
// ★ 系统级面（homeos / calendar）的**特例**：
//
//	PRD 3.9.7 明确写了「恒启用、恒出生，「未启用」「即将上线」对它不适用，
//	服务不可达时只记「暂不可用」」。
//	所以判定顺序上，系统级面要在**最前面**短路，
//	不能先走「服务没部署 → 即将上线」那条分支。
func Decide(d Domain, st State) (string, string) {
	// ① 系统级面：先判「是否可达」，其余一律不适用
	if d.SysLevel {
		if st.ServiceReachable {
			return "正常", "面可用，无降级"
		}
		// 关键：不管 ServiceDeployed 是 true 还是 false，都判「暂不可用」
		return "暂不可用", "系统级面恒启用恒出生，不可达一律记「暂不可用」（PRD 3.9.7）"
	}

	// ② 业务面：按四降级词正常判定
	if d.Dependency != "" && !st.DependencyOK {
		return "依赖未就绪", "本面可用，但它依赖的另一面没出生"
	}
	if !st.ServiceDeployed {
		return "即将上线", "这个面还没出生（服务不存在）"
	}
	if !st.ModuleEnabled {
		return "未启用", "本家庭没挂载这个面"
	}
	if !st.ServiceReachable {
		return "暂不可用", "面已启用，但本次服务不可达"
	}
	return "正常", "面可用，无降级"
}

func main() {
	fmt.Println("=== W32 d29 · 降级词：calendar 恒启用恒出生 ===")
	fmt.Println()
