type Rule struct {
	ID    string
	Desc  string
	Grep  string
	Scope string
	Viols []Line
	Allow string // 允许的例外
}

func analyze() []Rule {
	rules := []Rule{
		{
			ID: "B1", Desc: "calendar 的代码不出现 homeos_ 表名",
			Grep:  `grep -rn "homeos_" server/internal/calendar/ | grep -v "_test.go"`,
			Scope: "server/internal/calendar/",
		},
		{
			ID: "B2", Desc: "homeos 的代码不出现 calendar_ 表名",
			Grep:  `grep -rn "calendar_" server/internal/homeos/ | grep -v "_test.go"`,
			Scope: "server/internal/homeos/",
		},
		{
			ID: "B3", Desc: "homeos 的代码不注册 /api/calendar/*",
			Grep:  `grep -rn '"/api/calendar' server/internal/homeos/`,
			Scope: "server/internal/homeos/",
		},
		{
			ID: "B4", Desc: "homeos 的代码不发布 calendar. 前缀事件",
			Grep:  `grep -rn '"calendar\.' server/internal/homeos/`,
			Scope: "server/internal/homeos/",
		},
		{
			ID: "B5", Desc: "calendar 的代码不发布 homeos. 前缀事件",
			Grep:  `grep -rn '"homeos\.' server/internal/calendar/`,
			Scope: "server/internal/calendar/",
		},
		{
			ID: "B6", Desc: "两端都不出现对方的表前缀（跨 schema 直查）",
			Grep:  `grep -rn "FROM homeos\.\|FROM calendar\." server/internal/ | grep -v "自己域"`,
			Scope: "server/internal/",
		},
	}

	for _, l := range lines {
		for i := range rules {
			r := &rules[i]
			if r.Scope != "" && !strings.Contains(l.Dir, strings.TrimSuffix(strings.Split(strings.TrimSuffix(r.Scope, "/"), "/")[0]+"/", "/")) {
				// 简化：只按 Dir 判断
			}
		}
	}

	// 逐条匹配
	match := func(r *Rule, l Line) bool {
		switch r.ID {
		case "B1":
			return l.Dir == "calendar" && strings.Contains(l.Text, "homeos_")
		case "B2":
			return l.Dir == "homeos" && strings.Contains(l.Text, "calendar_")
		case "B3":
			return l.Dir == "homeos" && strings.Contains(l.Text, "/api/calendar")
		case "B4":
			return l.Dir == "homeos" && strings.Contains(l.Text, "\"calendar.")
		case "B5":
			return l.Dir == "calendar" && strings.Contains(l.Text, "\"homeos.")
		case "B6":
			// 自己域的 FROM 不算
			if strings.Contains(l.Text, "FROM homeos.") && l.Dir == "homeos" {
				return false
			}
			if strings.Contains(l.Text, "FROM calendar.") && l.Dir == "calendar" {
				return false
			}
			if strings.Contains(l.Text, "FROM homeos.") && l.Dir == "calendar" {
				return true
			}
			if strings.Contains(l.Text, "FROM calendar.") && l.Dir == "homeos" {
				return true
			}
			return false
		}
		return false
	}

	for _, l := range lines {
		for i := range rules {
			if match(&rules[i], l) {
				rules[i].Viols = append(rules[i].Viols, l)
			}
		}
	}
	return rules
}

