	fmt.Println("=== 2. 冻结后的变更分级 ===")
	fmt.Println()
	fmt.Println("  冻结不等于「不能改」，而是「改要走流程」。分级：")
	fmt.Println()
	fmt.Printf("  %s %s %s %s\n", pad("变更类型", 24), pad("分级", 14), pad("允许", 8), "例子")
	fmt.Println("  " + strings.Repeat("-", 116))
	for _, c := range changes {
		ok := "可以"
		if !c.Allowed {
			ok = "**不行**"
		}
		fmt.Printf("  %s %s %s %s\n", pad(c.Name, 24), pad(c.Level, 14), pad(ok, 8), c.Example)
	}
	fmt.Println()
	compatN, breakN, forbidN := 0, 0, 0
	for _, c := range changes {
		switch c.Level {
		case "兼容变更":
			compatN++
		case "破坏性变更":
			breakN++
		default:
			forbidN++
		}
	}
	fmt.Printf("  兼容变更 %d 类（可以）· 破坏性变更 %d 类（要走流程）· 绝对禁止 %d 类\n\n",
		compatN, breakN, forbidN)

	// ---------------- 3. 流程 ----------------
	fmt.Println("=== 3. 兼容变更的流程（唯一被允许的路）===")
	fmt.Println()
	flow := []string{
		"① 提 ADR：在 notes/adr/ 下写一页，说清「为什么加、影响谁、怎么回滚」",
		"② 改登记面：openapi/calendar.yaml 或 events/calendar.yaml 加条目",
		"③ 跑契约门禁：scripts/check-contract.sh —— 确认是**新增**不是修改",
		"④ 评审签字：至少两个人，其中一个不是这次改动的作者",
		"⑤ 更新哈希基线：scripts/contract-freeze.sh --update",
		"⑥ 才写实现：先测试后实现（S3 d22 的顺序）",
		"⑦ 合并前跑全量门禁 + 端到端测试",
	}
	for _, f := range flow {
		fmt.Printf("  %s\n", f)
	}
	fmt.Println()
	fmt.Println("  第 ⑤ 步是关键：**哈希基线的更新必须单独一次提交**。")
	fmt.Println("  混在代码改动里，就分不清「这次改的是契约」还是「这次改的是实现」。")
	fmt.Println()

	// ---------------- 4. 门禁脚本 ----------------
	fmt.Println("=== 4. 冻结的机械形态：哈希比对 ===")
	fmt.Println()
	fmt.Println("  基线文件：server/contracts/FROZEN.yaml")
	fmt.Println()
	frozen := `  # server/contracts/FROZEN.yaml
  # 生成时间：2026-03-18
  # 冻结范围：svc-calendar（P1-M1）
  contracts:
    openapi/calendar.yaml:
      hash: sha256:a3f19c2d...
      entries: 9
      breaking_change: "不允许"
    events/calendar.yaml:
      hash: sha256:b7e241af...
      entries: 2
      breaking_change: "不允许"
    migrations/calendar:
      hash: sha256:c1d877b0...
      files: 4
      breaking_change: "绝对禁止修改已执行的文件"
    enums:
      hash: sha256:d5a033e6...
      repeat: 7        # 七种表达法
      visibility: 3
      status_todo: 4
      status_reminder: 3
      channel: 3
      breaking_change: "只能加不能删"`
	fmt.Println(frozen)
	fmt.Println()
	fmt.Println("  门禁脚本：")
	fmt.Println()
	script := `  #!/usr/bin/env bash
  # scripts/check-contract-frozen.sh
  set -euo pipefail

  cd "$(dirname "$0")/.."

  # 计算四份契约的当前哈希
  cur_openapi=$(sha256sum server/contracts/openapi/calendar.yaml       | cut -d' ' -f1)
  cur_events=$( sha256sum server/contracts/events/calendar.yaml        | cut -d' ' -f1)
  cur_migr=$(  find server/migrations/calendar -name '*.sql' | sort \
              | xargs sha256sum | sha256sum | cut -d' ' -f1)
  cur_enums=$( grep -rhoE "'(family|members|private|time|location|due|open|done|archived|cancelled|active|paused|fired|inapp|push|sms)'" \
              server/internal/calendar/model/ | sort -u | sha256sum | cut -d' ' -f1)

  # 与基线比对
  chk() {
    if [ "$2" = "$3" ]; then
      printf "  PASS  %s 未变\n" "$1"
    else
      printf "  FAIL  %s 变了（基线 %s → 当前 %s）\n" "$1" "${2:0:12}" "${3:0:12}"
      FAIL=$((FAIL+1))
    fi
  }

  FAIL=0
  chk "接口登记面" "$(yq '.contracts.\"openapi/calendar.yaml\".hash' server/contracts/FROZEN.yaml)" "$cur_openapi"
  chk "事件目录"   "$(yq '.contracts.\"events/calendar.yaml\".hash'  server/contracts/FROZEN.yaml)" "$cur_events"
  chk "数据模型"   "$(yq '.contracts.\"migrations/calendar\".hash'    server/contracts/FROZEN.yaml)" "$cur_migr"
  chk "枚举取值"   "$(yq '.contracts.enums.hash'                       server/contracts/FROZEN.yaml)" "$cur_enums"

  echo
  if [ "$FAIL" -gt 0 ]; then
    echo "契约已变。若为兼容变更（新增），走流程："
    echo "  1. 提 ADR          2. 改登记面     3. 评审签字"
    echo "  4. scripts/contract-freeze.sh --update"
    echo "若是破坏性变更，P1 阶段不做。"
    exit 1
  fi`
	fmt.Println(script)
	fmt.Println()
	fmt.Println("  四份哈希的设计要点：")
	fmt.Println()
	hn := []string{
		"**登记面用整文件哈希** —— 任何改动（含注释）都会被抓到。",
		"    代价：改个注释也要更新基线。这是有意的 —— 登记面不该有随意改动。",
		"**迁移用「文件列表 + 内容」的二次哈希** —— 因为目录里文件会增（兼容变更）。",
		"    注意是 sort 后哈希，保证文件顺序不影响结果。",
		"**枚举用「取值集合」的哈希** —— 只对取值敏感，不对顺序敏感。",
		"    这样新增取值时能通过 —— 而新增正是我们允许的。",
	}
	for _, n := range hn {
		fmt.Printf("  · %s\n\n", n)
	}

	// ---------------- 5. 解冻判据 ----------------
	fmt.Println("=== 5. 什么时候可以解冻 ===")
	fmt.Println()
	fmt.Println("  解冻 = 走「破坏性变更」流程。判据有三条，**必须同时满足**：")
	fmt.Println()
	thaw := []struct{ No, Crit, Meaning string }{
		{"1", "所有下游都已升级",
			"下游包括：客户端（必须发版且用户升级）、homeos（必须先部署新版本）。\n     客户端无法强制升级 —— 所以这一条实际上很难满足。"},
		{"2", "有回滚方案且已演练",
			"不是「能回滚」，是「已演练过回滚」。\n     契约变更的回滚比代码回滚难：数据已经按新格式写了。"},
		{"3", "有版本化机制",
			"路径带版本号（/api/v2/calendar/*）或请求头带版本。\n     **本项目 P1 阶段没有版本化** —— 所以解冻能力事实上不存在。"},
	}
	for _, t := range thaw {
		fmt.Printf("  判据 %s  %s\n", t.No, t.Crit)
		for _, l := range strings.Split(t.Meaning, "\n") {
			fmt.Printf("          %s\n", l)
		}
		fmt.Println()
	}
	fmt.Println("  三条同时满足才能解冻。当前 P1 阶段第 3 条不满足，")
	fmt.Println("  所以结论很明确：**P1 阶段内 calendar 契约实质上不可解冻。**")
	fmt.Println()
	fmt.Println("  这不是缺陷，是**约束**。没有版本化就不该破坏契约 ——")
	fmt.Println("  否则每次改动都是一次「全体客户端必须升级」。")
	fmt.Println()

	// ---------------- 6. S9/S13 会被卡在哪 ----------------
	fmt.Println("=== 6. 冻结对下游的影响：S9 与 S13 会撞到什么 ===")
	fmt.Println()
	down := []struct{ Stage, Want, Blocked, How string }{
		{"S9", "到期注册契约", "不能改 GET /api/calendar/events 的出参",
			"注册走**新事件** {code}.due.registered，不走 HTTP。\n     现有 9 条接口一行不动"},
		{"S9", "注册时需要知道来源对象", "不能用现有的 source_system/source_id 字段改语义",
			"那两个字段的含义不变。注册走事件 payload 传新的字段名"},
		{"S13", "finance 注册账单到期", "不能在 finance 里直查 calendar 表",
			"finance 发 {code}.due.registered，calendar 消费后落表。\n     与 S9 的机制完全一致"},
		{"S13", "finance 想加「每月提醒还房贷」", "不能新建一张 calendar_ 命名的表放 finance 的数据",
			"违反七类命名同源。数据在 finance_schema，写在 finance 的表里"},
	}
	for _, d := range down {
		fmt.Printf("  %s：%s\n", pad(d.Stage, 8), d.Want)
		fmt.Printf("     卡住  %s\n", d.Blocked)
		fmt.Printf("     绕法  %s\n\n", d.How)
	}
	fmt.Println("  四行「绕法」全部是**新增**，没有一处是「修改」。")
	fmt.Println("  这说明冻结与后续需求是兼容的 —— 只要需求本身是新的。")
	fmt.Println("  而 PRD 的到期注册设计（16.4）本来就是「新增注册契约」而不是")
	fmt.Println("  「改造现有接口」—— 这不是巧合，是 PRD 早就按「接口要冻结」的方式设计的。")
	fmt.Println()

	// ---------------- 7. 小结 ----------------
	fmt.Println("=== 7. W33 d34 小结 ===")
	fmt.Println()
	fmt.Println("  ① 冻结四份契约：接口登记面 / 事件目录 / 数据模型 / 枚举取值")
	fmt.Println("  ② 冻结的机械形态 = 四个 sha256，CI 逐个比对")
	fmt.Println("  ③ 枚举哈希只对取值集合敏感 → 新增取值能通过（这是我们要的）")
	fmt.Println("  ④ 变更分三级：兼容（可）/ 破坏（走流程）/ 绝对禁止")
	fmt.Println("  ⑤ 兼容变更的流程七步，其中「哈希基线单独提交」是关键")
	fmt.Println("  ⑥ 解冻三条判据，P1 阶段第 3 条（版本化）不满足 → 实质不可解冻")
	fmt.Println("  ⑦ S9/S13 的需求都是「新增」，与冻结兼容 —— 实测四处绕法全为新增")
	fmt.Println()
	fmt.Println("  明天讲本阶段真实坑清单：从 S0 到 S8 积累的那些坑。")
}
